-- ════════════════════════════════════════════════════════
-- 218 — Lot 5 bis du troisieme recensement : quarante lignes dans les gammes
-- ────────────────────────────────────────────────────────
-- Aucune maison creee. Des noms que le recensement testait comme des
-- maisons et qui sont des lignes entrent dans le `gamme` de celle qui
-- les possede, six langues, chacun avec une notice qui dit ce qu'il est.
-- Treize maisons, quarante lignes :
--   Foundation         Tabernacle, Highclere Castle, Olmec
--   Dunbarton          Umbagog, Muestra de Saka
--   Alec Bradley       Black Market, Magic Toast, Project 40, Kintsugi
--   Crowned Heads      Headley Grange, Jericho Hill, Las Calaveras,
--                      La Imperiosa, Mil Dias
--   Illusione          Cruzado, Rothchildes, Fume d'Amour, OneOff, Garagiste
--   Southern Draw      Quickdraw, Firethorn, Desert Rose, Fraternal Order
--   Drew Estate        Nica Rustica, Herrera Esteli Norteno
--   My Father          Jaime Garcia RE, Flor de las Antillas, La Duena,
--                      El Centurion
--   Tatuaje            Black Label, La Riqueza, Monster Series, Ambos Mundos
--   Fratello           Classico
--   262                Allegiance
--   HVC                La Rosa 520, San Isidro, Cerro
--   Cornelius & A.     Meridian, Venganza, The Gent
--
-- NON RANGEES, et pourquoi : Tabak Especial, Deadwood, Isla del Sol
-- (Drew Estate) sont des cigares infuses — l'atlas porte ACID, mais on
-- n'ajoute pas trois infusions de plus sans que la fiche en dise la
-- regle ; Indomina, Ultra, Haut 10, MJ12, Polpette, Stillwell Star,
-- Red Meat Lovers, Fine & Rare, Gatekeeper, Filthy Hooligan (en note de
-- Black Market), Court Reserve, Juarez — non sources dans ce lot.
--
-- `gamme` lu dans la base et reecrit en litteral complet.
-- ════════════════════════════════════════════════════════

-- ── Foundation Cigar Company ──
UPDATE `brands` SET `gamme` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","wrapper":"Corojo 99 de Jalapa","vitolas":["Corona Gorda","Toro"],"story":"L''assemblage fondateur, nommé d''après une satire coloniale transmise oralement pendant des siècles. Bois, cuir, une pointe de sucre roux, et une évolution nette entre le premier et le dernier tiers."},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":["Robusto"],"story":"La racine nord de la maison : cape du Connecticut sur tripe nicaraguayenne. Sombre, terreux, sans amertume — et volontairement placé dans une gamme de prix accessible."},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf du Connecticut","vitolas":[],"story":"2016 — la ligne corsée, cape broadleaf, chez A.J. Fernández ; le recensement de cet atlas la prenait pour une maison."},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut d''Équateur","vitolas":[],"story":"2017 — le château de Downton Abbey sur une bague, Connecticut d''Équateur."},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"PCA 2022 — un hommage au Mexique et à ses Olmèques, cape San Andrés, Claro et Maduro."}]' WHERE `name` = 'Foundation Cigar Company';
UPDATE `brands` SET `gamme_en` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","wrapper":"Jalapa Corojo 99","vitolas":["Corona Gorda","Toro"],"story":"The founding blend, named after a colonial satire passed down orally for centuries. Wood, leather, a hint of brown sugar, and a clear evolution between the first and the last third."},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":["Robusto"],"story":"The northern root of the house: Connecticut wrapper over Nicaraguan filler. Dark, earthy, without bitterness — and deliberately kept in an affordable price range."},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","wrapper":"Connecticut broadleaf","vitolas":[],"story":"2016 — the full-bodied line, broadleaf wrapper, at A.J. Fernández; this atlas''s census took it for a house."},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","wrapper":"Ecuadorian Connecticut","vitolas":[],"story":"2017 — the castle of Downton Abbey on a band, Ecuadorian Connecticut."},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"PCA 2022 — a tribute to Mexico and its Olmecs, San Andrés wrapper, Claro and Maduro."}]' WHERE `name` = 'Foundation Cigar Company';
UPDATE `brands` SET `gamme_es` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","wrapper":"Corojo 99 de Jalapa","vitolas":["Corona Gorda","Toro"],"story":"La liga fundacional, con el nombre de una sátira colonial transmitida oralmente durante siglos. Madera, cuero, una pizca de azúcar moreno, y una evolución neta entre el primer y el último tercio."},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":["Robusto"],"story":"La raíz norte de la casa: capa del Connecticut sobre tripa nicaragüense. Oscuro, terroso, sin amargor — y situado a propósito en una gama de precios accesible."},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf de Connecticut","vitolas":[],"story":"2016 — la línea fuerte, capa broadleaf, en A.J. Fernández; el censo de este atlas la tomaba por una casa."},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut de Ecuador","vitolas":[],"story":"2017 — el castillo de Downton Abbey en una anilla, Connecticut de Ecuador."},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","wrapper":"San Andrés (México)","vitolas":[],"story":"PCA 2022 — un homenaje a México y a sus olmecas, capa San Andrés, Claro y Maduro."}]' WHERE `name` = 'Foundation Cigar Company';
UPDATE `brands` SET `gamme_de` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","wrapper":"Corojo 99 aus Jalapa","vitolas":["Corona Gorda","Toro"],"story":"Der Gründungsblend, benannt nach einer kolonialen Satire, die über Jahrhunderte mündlich überliefert wurde. Holz, Leder, ein Anflug von braunem Zucker und eine klare Entwicklung zwischen erstem und letztem Drittel."},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":["Robusto"],"story":"Die nördliche Wurzel des Hauses: Connecticut-Deckblatt über nicaraguanischer Einlage. Dunkel, erdig, ohne Bitterkeit — und bewusst in einer erschwinglichen Preislage gehalten."},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","wrapper":"Connecticut-Broadleaf","vitolas":[],"story":"2016 — die kräftige Linie, Broadleaf-Deckblatt, bei A.J. Fernández; die Zählung dieses Atlas hielt sie für ein Haus."},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","wrapper":"Ecuadorianisches Connecticut","vitolas":[],"story":"2017 — das Schloss von Downton Abbey auf einer Bauchbinde, ecuadorianisches Connecticut."},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"PCA 2022 — eine Hommage an Mexiko und seine Olmeken, San-Andrés-Deckblatt, Claro und Maduro."}]' WHERE `name` = 'Foundation Cigar Company';
UPDATE `brands` SET `gamme_zh` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","wrapper":"哈拉帕可乐多99","vitolas":["Corona Gorda","Toro"],"story":"奠基配方，得名于一出口传数百年的殖民时期讽刺剧。木质、皮革，一丝红糖，从第一段到最后一段有清晰的推进。"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":["Robusto"],"story":"这家的北方之根：康涅狄格茄衣配尼加拉瓜茄芯。深色、带土味、不苦——并有意保持在可及的价位。"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","wrapper":"康涅狄格 broadleaf","vitolas":[],"story":"2016年——浓烈的一线，broadleaf 茄衣，在 A.J. Fernández 制作；本图集的普查曾把它当作一家公司。"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","wrapper":"厄瓜多尔康涅狄格","vitolas":[],"story":"2017年——茄标上的唐顿庄园城堡，厄瓜多尔康涅狄格茄衣。"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","wrapper":"圣安德烈斯（墨西哥）","vitolas":[],"story":"2022年 PCA——向墨西哥及其奥尔梅克人致敬，圣安德烈斯茄衣，Claro 与 Maduro。"}]' WHERE `name` = 'Foundation Cigar Company';
UPDATE `brands` SET `gamme_ar` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","wrapper":"كوروخو 99 من خالابا","vitolas":["Corona Gorda","Toro"],"story":"الخلطة التأسيسية، المسمّاة على هجائية استعمارية تناقلتها الأفواه قروناً. خشب وجلد ولمسة سكر بنّي، مع تطوّر واضح بين الثلث الأول والأخير."},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":["Robusto"],"story":"الجذر الشمالي للدار: غلاف كونيتيكت على حشوة نيكاراغوية. داكن، ترابي، بلا مرارة — وموضوع عمداً في نطاق سعري في المتناول."},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","wrapper":"برودليف كونيتيكت","vitolas":[],"story":"2016 — الخطّ القويّ، غلاف برودليف، لدى A.J. Fernández؛ وكان إحصاء هذا الأطلس يحسبه دارًا."},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","wrapper":"كونيتيكت إكوادوري","vitolas":[],"story":"2017 — قصر داونتون آبي على حزام، كونيتيكت إكوادوري."},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","wrapper":"سان أندريس (المكسيك)","vitolas":[],"story":"PCA 2022 — تحيّة للمكسيك وأولميكها، غلاف سان أندريس، Claro وMaduro."}]' WHERE `name` = 'Foundation Cigar Company';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : foundationcigarcompany.com et cigar-coop.com « Foundation Cigar Company to Introduce Olmec at 2022 PCA Trade Show » (Tabernacle, 2016, broadleaf ; Highclere Castle, 2017, Connecticut d''Équateur ; Olmec, PCA 2022, San Andrés — toutes chez A.J. Fernández)') WHERE `name` = 'Foundation Cigar Company' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── Dunbarton Tobacco & Trust ──
UPDATE `brands` SET `gamme` = '[{"name":"Sobremesa","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano d''Équateur","vitolas":["Robusto","Toro","Corona","Elegante"],"story":"La première gamme, sortie en 2015. Cape Habano d''Équateur, sous-cape San Andrés du Mexique, tripe nicaraguayenne complétée d''un ligero de Pennsylvanie — une feuille que peu de maisons emploient."},{"name":"Mi Querida","color":"#4A2C1A","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":["Fino Largo","Triqui Traca"],"story":"Cape Connecticut Broadleaf sombre sur un cœur entièrement nicaraguayen. C''est la gamme roulée à la NACSA, sous la conduite de Raul Disla."},{"name":"Sin Compromiso","color":"#3A2A20","force":"Full","wrapper":"San Andrés Negro","vitolas":["Selección No. 5","Parejo No. 2"],"story":"Roulée à la Joya de Nicaragua. Cape San Andrés Negro dite « Cultivo Tonto », sous-cape Habano d''Équateur en ligero fin, tripes nicaraguayennes de plantations choisies une à une."},{"name":"Todos Las Dias","color":"#6B4226","force":"Full","wrapper":"Nicaragua","vitolas":["Robusto","Toro"],"story":"Le puro nicaraguayen de la maison — cape, sous-cape et tripe du même pays — roulé à la Joya de Nicaragua. Le nom dit l''intention : un cigare de tous les jours, à un niveau de force qui ne l''est pas."},{"name":"Umbagog","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf du Connecticut","vitolas":[],"story":"2017 — les broadleaf trop rustiques pour Mi Querida, roulés à part et vendus moins cher ; du nom d''un lac du New Hampshire."},{"name":"Muestra de Saka","color":"#7A2E1E","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Depuis 2016 — la série d''essais de Steve Saka, un assemblage à la fois, en petites boîtes."}]' WHERE `name` = 'Dunbarton Tobacco & Trust';
UPDATE `brands` SET `gamme_en` = '[{"name":"Sobremesa","color":"#8B5A2B","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":["Robusto","Toro","Corona","Elegante"],"story":"The first range, out in 2015. Ecuadorian Habano wrapper, Mexican San Andrés binder, Nicaraguan filler completed with a Pennsylvania ligero — a leaf few houses use."},{"name":"Mi Querida","color":"#4A2C1A","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":["Fino Largo","Triqui Traca"],"story":"A dark Connecticut Broadleaf wrapper over a wholly Nicaraguan core. This is the range rolled at NACSA, under Raul Disla."},{"name":"Sin Compromiso","color":"#3A2A20","force":"Full","wrapper":"San Andrés Negro","vitolas":["Selección No. 5","Parejo No. 2"],"story":"Rolled at Joya de Nicaragua. San Andrés Negro wrapper called \\"Cultivo Tonto\\", a thin Ecuadorian Habano ligero binder, Nicaraguan fillers from plantations chosen one by one."},{"name":"Todos Las Dias","color":"#6B4226","force":"Full","wrapper":"Nicaragua","vitolas":["Robusto","Toro"],"story":"The house''s Nicaraguan puro — wrapper, binder and filler from the one country — rolled at Joya de Nicaragua. The name states the intent: an everyday cigar, at a strength that is not."},{"name":"Umbagog","color":"#3A2A1E","force":"Full","wrapper":"Connecticut broadleaf","vitolas":[],"story":"2017 — the broadleaf too rustic for Mi Querida, rolled apart and sold cheaper; named after a New Hampshire lake."},{"name":"Muestra de Saka","color":"#7A2E1E","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"Since 2016 — Steve Saka''s trial series, one blend at a time, in small boxes."}]' WHERE `name` = 'Dunbarton Tobacco & Trust';
UPDATE `brands` SET `gamme_es` = '[{"name":"Sobremesa","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":["Robusto","Toro","Corona","Elegante"],"story":"La primera gama, salida en 2015. Capa Habano de Ecuador, capote San Andrés de México, tripa nicaragüense completada con un ligero de Pensilvania: una hoja que pocas casas emplean."},{"name":"Mi Querida","color":"#4A2C1A","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":["Fino Largo","Triqui Traca"],"story":"Capa Connecticut Broadleaf oscura sobre un corazón enteramente nicaragüense. Es la gama liada en NACSA, bajo la conducción de Raul Disla."},{"name":"Sin Compromiso","color":"#3A2A20","force":"Full","wrapper":"San Andrés Negro","vitolas":["Selección No. 5","Parejo No. 2"],"story":"Liada en Joya de Nicaragua. Capa San Andrés Negro llamada «Cultivo Tonto», capote de ligero fino Habano de Ecuador, tripas nicaragüenses de plantaciones escogidas una a una."},{"name":"Todos Las Dias","color":"#6B4226","force":"Full","wrapper":"Nicaragua","vitolas":["Robusto","Toro"],"story":"El puro nicaragüense de la casa — capa, capote y tripa del mismo país — liado en Joya de Nicaragua. El nombre dice la intención: un puro de todos los días, con una fuerza que no lo es."},{"name":"Umbagog","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf de Connecticut","vitolas":[],"story":"2017 — los broadleaf demasiado rústicos para Mi Querida, liados aparte y vendidos más baratos; por un lago de New Hampshire."},{"name":"Muestra de Saka","color":"#7A2E1E","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Desde 2016 — la serie de ensayos de Steve Saka, una ligada a la vez, en cajas pequeñas."}]' WHERE `name` = 'Dunbarton Tobacco & Trust';
UPDATE `brands` SET `gamme_de` = '[{"name":"Sobremesa","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano aus Ecuador","vitolas":["Robusto","Toro","Corona","Elegante"],"story":"Die erste Linie, 2015 erschienen. Deckblatt Habano aus Ecuador, Umblatt San Andrés aus Mexiko, nicaraguanische Einlage, ergänzt durch einen Ligero aus Pennsylvania — ein Blatt, das wenige Häuser verwenden."},{"name":"Mi Querida","color":"#4A2C1A","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":["Fino Largo","Triqui Traca"],"story":"Dunkles Connecticut-Broadleaf-Deckblatt über einem vollständig nicaraguanischen Kern. Diese Linie wird bei NACSA gerollt, unter Raul Disla."},{"name":"Sin Compromiso","color":"#3A2A20","force":"Full","wrapper":"San Andrés Negro","vitolas":["Selección No. 5","Parejo No. 2"],"story":"Bei Joya de Nicaragua gerollt. Deckblatt San Andrés Negro namens \\"Cultivo Tonto\\", Umblatt aus dünnem ecuadorianischem Habano-Ligero, nicaraguanische Einlagen von einzeln ausgewählten Pflanzungen."},{"name":"Todos Las Dias","color":"#6B4226","force":"Full","wrapper":"Nicaragua","vitolas":["Robusto","Toro"],"story":"Der nicaraguanische Puro des Hauses — Deckblatt, Umblatt und Einlage aus einem Land — bei Joya de Nicaragua gerollt. Der Name sagt die Absicht: eine Alltagszigarre, in einer Stärke, die es nicht ist."},{"name":"Umbagog","color":"#3A2A1E","force":"Full","wrapper":"Connecticut-Broadleaf","vitolas":[],"story":"2017 — die für Mi Querida zu rustikalen Broadleaf, getrennt gerollt und günstiger verkauft; nach einem See in New Hampshire."},{"name":"Muestra de Saka","color":"#7A2E1E","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Seit 2016 — Steve Sakas Versuchsreihe, ein Blend nach dem anderen, in kleinen Kisten."}]' WHERE `name` = 'Dunbarton Tobacco & Trust';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Sobremesa","color":"#8B5A2B","force":"Medium-Full","wrapper":"厄瓜多尔 Habano","vitolas":["Robusto","Toro","Corona","Elegante"],"story":"2015 年问世的第一条线。厄瓜多尔 Habano 茄衣，墨西哥圣安德烈斯茄套，尼加拉瓜茄芯并辅以宾夕法尼亚 ligero——这是少有品牌使用的一种烟叶。"},{"name":"Mi Querida","color":"#4A2C1A","force":"Full","wrapper":"康涅狄格宽叶","vitolas":["Fino Largo","Triqui Traca"],"story":"深色康涅狄格宽叶茄衣，内里全为尼加拉瓜烟叶。这条线在 NACSA 卷制，由 Raul Disla 主持。"},{"name":"Sin Compromiso","color":"#3A2A20","force":"Full","wrapper":"圣安德烈斯 Negro","vitolas":["Selección No. 5","Parejo No. 2"],"story":"在 Joya de Nicaragua 卷制。茄衣为称作「Cultivo Tonto」的圣安德烈斯 Negro，茄套为厄瓜多尔 Habano 薄 ligero，茄芯来自逐一挑选的尼加拉瓜种植园。"},{"name":"Todos Las Dias","color":"#6B4226","force":"Full","wrapper":"尼加拉瓜","vitolas":["Robusto","Toro"],"story":"这家的尼加拉瓜纯产雪茄——茄衣、茄套与茄芯同出一国——在 Joya de Nicaragua 卷制。名字道出意图：一支日常的雪茄，只是它的浓度并不日常。"},{"name":"Umbagog","color":"#3A2A1E","force":"Full","wrapper":"康涅狄格 broadleaf","vitolas":[],"story":"2017年——对 Mi Querida 而言过于粗犷的 broadleaf，另行卷制、售价更低；以新罕布什尔的一座湖命名。"},{"name":"Muestra de Saka","color":"#7A2E1E","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"自2016年——史蒂夫·萨卡的试验系列，一次一款配方，小盒装。"}]' WHERE `name` = 'Dunbarton Tobacco & Trust';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Sobremesa","color":"#8B5A2B","force":"Medium-Full","wrapper":"هابانو إكوادوري","vitolas":["Robusto","Toro","Corona","Elegante"],"story":"السلسلة الأولى، صدرت عام 2015. غلاف هابانو إكوادوري، ورابط سان أندريس مكسيكي، وحشوة نيكاراغوية مكمَّلة بليغيرو من بنسلفانيا — وهو ورق قلّ أن تستعمله الدور."},{"name":"Mi Querida","color":"#4A2C1A","force":"Full","wrapper":"كونيتيكت برودليف","vitolas":["Fino Largo","Triqui Traca"],"story":"غلاف كونيتيكت برودليف داكن فوق قلب نيكاراغوي بالكامل. وهي السلسلة الملفوفة في ناكسا بإشراف راؤول ديسلا."},{"name":"Sin Compromiso","color":"#3A2A20","force":"Full","wrapper":"سان أندريس نيغرو","vitolas":["Selección No. 5","Parejo No. 2"],"story":"تُلَفّ في خويا دي نيكاراغوا. غلاف سان أندريس نيغرو يُدعى «كولتيفو تونتو»، ورابط من ليغيرو هابانو إكوادوري رفيع، وحشوات نيكاراغوية من مزارع منتقاة واحدة واحدة."},{"name":"Todos Las Dias","color":"#6B4226","force":"Full","wrapper":"نيكاراغوا","vitolas":["Robusto","Toro"],"story":"سيجار الدار النيكاراغوي الخالص — غلافًا ورابطًا وحشوة من بلد واحد — ملفوف في خويا دي نيكاراغوا. والاسم يقول المقصد: سيجار كلّ يوم، بقوّة ليست كذلك."},{"name":"Umbagog","color":"#3A2A1E","force":"Full","wrapper":"برودليف كونيتيكت","vitolas":[],"story":"2017 — أوراق البرودليف الأخشن من أن تصلح لـMi Querida، تُلفّ على حدة وتُباع أرخص؛ باسم بحيرة في نيوهامبشير."},{"name":"Muestra de Saka","color":"#7A2E1E","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"منذ 2016 — سلسلة تجارب ستيف ساكا، مزجة في كلّ مرّة، في علب صغيرة."}]' WHERE `name` = 'Dunbarton Tobacco & Trust';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : dunbartoncigars.com (Umbagog, 2017, broadleaf, chez Joya de Nicaragua ; Muestra de Saka, la série d''essais de Steve Saka depuis 2016)') WHERE `name` = 'Dunbarton Tobacco & Trust' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── Alec Bradley ──
UPDATE `brands` SET `gamme` = '[{"name":"Prensado","color":"#8B2500","force":"Full","story":"Format Torpedo (52 x 152mm) pressé en boîte. Assemblage hondurien, guatémaltèque et nicaraguayen, cape Jamastrán du Honduras. Notes de poivre noir intense, café espresso, noix de cajou grillée. La section rectangulaire change la combustion — les arômes en sortent plus concentrés.","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"Jamastran du Honduras"},{"name":"Tempus","color":"#722F37","force":"Medium-Full","story":"Lancée en 2008. Assemblage hondurien et nicaraguayen, cape d''Équateur. Notes de cuir, épices orientales, bois sombre. Mi-corsée à corsée, équilibrée. La gamme qui précédait le Prensado et qui reste la plus constante de la maison — disponible quand le Prensado est épuisé.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Équateur"},{"name":"Coyol","color":"#A0522D","force":"Medium","story":"Lancée en 2019, à prix doux. Cape Connecticut Shade sur assemblage d''Amérique centrale. Notes de noisette, crème, bois léger. L''entrée dans l''univers Alec Bradley pour qui découvre la maison.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Connecticut Shade"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"2011 — la bague noire ; Filthy Hooligan en est l''édition annuelle de la Saint-Patrick."},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano du Nicaragua","vitolas":[],"story":"2019 — né d''un toast porté sur une ferme du Nicaragua, dit la maison."},{"name":"Project 40","color":"#3E4A6B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"2019 — un cigare de prix contenu, du nom d''une heure de journée où l''on fume."},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","wrapper":"Habano du Nicaragua","vitolas":[],"story":"2021 — l''art japonais de réparer à l''or, pour un assemblage composé pendant la pandémie."}]' WHERE `name` = 'Alec Bradley';
UPDATE `brands` SET `gamme_en` = '[{"name":"Prensado","color":"#8B2500","force":"Full","story":"Box-pressed Torpedo (52 x 152mm). Honduran-Guatemalan-Nicaraguan blend, Honduran Jamastrán wrapper. Intense black pepper, espresso, roasted cashew. The rectangular section of the box press changes the burn — the aromas come out more concentrated.","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"Honduran Jamastran"},{"name":"Tempus","color":"#722F37","force":"Medium-Full","story":"Launched 2008, Honduran-Nicaraguan blend, Ecuadorian wrapper. Notes of leather, oriental spices, dark wood. Medium-Full, balanced. The range that preceded the Prensado and remains the house''s most consistent — available when the Prensado is sold out.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Ecuadorian"},{"name":"Coyol","color":"#A0522D","force":"Medium","story":"Launched 2019, affordable pricing. Connecticut Shade wrapper over Central American blend. Notes of hazelnut, cream, light wood. The entry into the Alec Bradley universe for enthusiasts discovering the house.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Connecticut Shade"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"2011 — the black band; Filthy Hooligan is its annual St. Patrick''s edition."},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicaraguan Habano","vitolas":[],"story":"2019 — born of a toast raised on a Nicaraguan farm, the house says."},{"name":"Project 40","color":"#3E4A6B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"2019 — a moderately priced cigar, named after a time of day when one smokes."},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","wrapper":"Nicaraguan Habano","vitolas":[],"story":"2021 — the Japanese art of mending with gold, for a blend composed during the pandemic."}]' WHERE `name` = 'Alec Bradley';
UPDATE `brands` SET `gamme_es` = '[{"name":"Prensado","color":"#8B2500","force":"Full","story":"Torpedo box-pressed (52 x 152mm). Liga hondureño-guatemalteco-nicaragüense, capa Jamastrán de Honduras. Pimienta negra intensa, espresso, anacardo tostado. La sección rectangular del prensado cambia la combustión: los aromas salen más concentrados.","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"Jamastran de Honduras"},{"name":"Tempus","color":"#722F37","force":"Medium-Full","story":"Lanzada en 2008, liga hondureño-nicaragüense, capa ecuatoriana. Cuero, especias orientales, madera oscura. Medio-fuerte y equilibrada. Es la gama que precedió al Prensado y sigue siendo la más constante de la casa: está disponible cuando el Prensado se agota.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Ecuador"},{"name":"Coyol","color":"#A0522D","force":"Medium","story":"Lanzada en 2019, de precio accesible. Capa Connecticut Shade sobre liga centroamericana. Avellana, crema, madera ligera. La entrada al universo Alec Bradley para quien descubre la casa.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Connecticut Shade"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"2011 — la anilla negra; Filthy Hooligan es su edición anual de San Patricio."},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano de Nicaragua","vitolas":[],"story":"2019 — nacido de un brindis en una finca de Nicaragua, dice la casa."},{"name":"Project 40","color":"#3E4A6B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"2019 — un puro de precio contenido, por una hora del día en que se fuma."},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","wrapper":"Habano de Nicaragua","vitolas":[],"story":"2021 — el arte japonés de reparar con oro, para una ligada compuesta durante la pandemia."}]' WHERE `name` = 'Alec Bradley';
UPDATE `brands` SET `gamme_de` = '[{"name":"Prensado","color":"#8B2500","force":"Full","story":"Box-pressed Torpedo (52 x 152 mm). Honduranisch-guatemaltekisch-nicaraguanische Mischung, Deckblatt Jamastrán aus Honduras. Kräftiger schwarzer Pfeffer, Espresso, geröstete Cashew. Der rechteckige Querschnitt verändert den Abbrand — die Aromen treten konzentrierter hervor.","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"Jamastran aus Honduras"},{"name":"Tempus","color":"#722F37","force":"Medium-Full","story":"2008 lanciert, honduranisch-nicaraguanische Mischung, ecuadorianisches Deckblatt. Leder, orientalische Gewürze, dunkles Holz. Mittelkräftig und ausgewogen. Die Serie ging dem Prensado voraus und bleibt die beständigste des Hauses — verfügbar, wenn der Prensado ausverkauft ist.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Ecuador"},{"name":"Coyol","color":"#A0522D","force":"Medium","story":"2019 lanciert, zu sanftem Preis. Deckblatt Connecticut Shade über zentralamerikanischer Mischung. Haselnuss, Sahne, leichtes Holz. Der Einstieg in die Welt von Alec Bradley für alle, die das Haus entdecken.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Connecticut Shade"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"2011 — die schwarze Bauchbinde; Filthy Hooligan ist ihre jährliche St.-Patrick''s-Edition."},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicaraguanisches Habano","vitolas":[],"story":"2019 — entstanden aus einem Trinkspruch auf einer Farm in Nicaragua, sagt das Haus."},{"name":"Project 40","color":"#3E4A6B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"2019 — eine preiswerte Zigarre, benannt nach einer Tageszeit, zu der man raucht."},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","wrapper":"Nicaraguanisches Habano","vitolas":[],"story":"2021 — die japanische Kunst, mit Gold zu reparieren, für einen während der Pandemie komponierten Blend."}]' WHERE `name` = 'Alec Bradley';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Prensado","color":"#8B2500","force":"Full","story":"方压鱼雷型（52 x 152 毫米）。洪都拉斯-危地马拉-尼加拉瓜配方，洪都拉斯哈马斯特兰茄衣。浓烈黑胡椒、浓缩咖啡、烤腰果。方压带来的矩形截面改变了燃烧方式——香气因此更为集中。","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"洪都拉斯 Jamastran"},{"name":"Tempus","color":"#722F37","force":"Medium-Full","story":"2008 年推出，洪都拉斯-尼加拉瓜配方，厄瓜多尔茄衣。皮革、东方香料、深色木质。中至浓郁而均衡。这个系列早于 Prensado，也始终是老号最稳定的一款——Prensado 断货时它还在。","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"厄瓜多尔"},{"name":"Coyol","color":"#A0522D","force":"Medium","story":"2019 年推出，价格友好。康涅狄格阴植茄衣，内裹中美洲配方。榛子、奶油、轻盈木质。这是初识这家老号的人进入 Alec Bradley 世界的入口。","vitolas":["Robusto","Toro","Corona"],"wrapper":"Connecticut Shade"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"2011年——黑色茄标；Filthy Hooligan 是它每年的圣帕特里克节版本。"},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","wrapper":"尼加拉瓜 Habano","vitolas":[],"story":"2019年——公司说，源于在尼加拉瓜一座农场上举杯的一次祝酒。"},{"name":"Project 40","color":"#3E4A6B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"2019年——一支价格克制的雪茄，以一天中抽烟的一个时刻命名。"},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","wrapper":"尼加拉瓜 Habano","vitolas":[],"story":"2021年——日本的金缮之艺，用于一款在疫情期间调配的配方。"}]' WHERE `name` = 'Alec Bradley';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Prensado","color":"#8B2500","force":"Full","story":"توربيدو مضغوط الشكل (52 × 152 مم). خلطة هندوراسية-غواتيمالية-نيكاراغوية، وغلاف خاماستران الهندوراسي. فلفل أسود حادّ، إسبريسّو، كاجو محمّص. المقطع المستطيل الناتج عن الضغط يغيّر الاحتراق — فتخرج العطور أكثر تركيزًا.","vitolas":["Torpedo","Robusto","Gordo","Double Toro","Corona Gorda"],"wrapper":"Jamastran من هندوراس"},{"name":"Tempus","color":"#722F37","force":"Medium-Full","story":"أُطلقت عام 2008، بخلطة هندوراسية-نيكاراغوية وغلاف إكوادوري. جلد، توابل شرقية، خشب داكن. متوسطة إلى ممتلئة ومتوازنة. سبقت المجموعةُ البرينسادو، وتظلّ أثبت ما في الدار — تجدها حين ينفد البرينسادو.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"إكوادوري"},{"name":"Coyol","color":"#A0522D","force":"Medium","story":"أُطلقت عام 2019 بسعر لطيف. غلاف كونيتيكت شيد فوق خلطة من أمريكا الوسطى. بندق، قشدة، خشب خفيف. إنها مدخل من يكتشف الدار إلى عالم أليك برادلي.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Connecticut Shade"},{"name":"Black Market","color":"#1F1F1F","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"2011 — الحزام الأسود؛ وFilthy Hooligan إصداره السنوي لعيد القدّيس باتريك."},{"name":"Magic Toast","color":"#8B5A2B","force":"Medium-Full","wrapper":"هابانو نيكاراغوي","vitolas":[],"story":"2019 — وُلد من نخبٍ رُفع في مزرعة نيكاراغوية، كما تقول الدار."},{"name":"Project 40","color":"#3E4A6B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"2019 — سيجار معتدل الثمن، باسم ساعة من النهار يُدخَّن فيها."},{"name":"Kintsugi","color":"#C9A96E","force":"Medium","wrapper":"هابانو نيكاراغوي","vitolas":[],"story":"2021 — الفنّ الياباني في الترميم بالذهب، لمزجة رُكّبت خلال الجائحة."}]' WHERE `name` = 'Alec Bradley';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : alecbradley.com (Black Market, 2011 ; Magic Toast, 2019 ; Project 40, 2019 ; Kintsugi, 2021)') WHERE `name` = 'Alec Bradley' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── Crowned Heads ──
UPDATE `brands` SET `gamme` = '[{"name":"Four Kicks","color":"#8B4513","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":["Corona Gorda","Robusto"],"story":"La gamme fondatrice, roulée à Estelí chez My Father. Corsée, poivrée, très construite — le style nicaraguayen vu par une maison qui n''a pas d''usine et choisit donc son rouleur."},{"name":"Le Carême","color":"#4A3728","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":["Toro"],"story":"Née d''une collaboration avec Ernesto Perez-Carrillo et roulée chez lui, en République dominicaine. Cape broadleaf sombre, cacao et café — rien à voir avec Four Kicks, et c''est le propos."},{"name":"Headley Grange","color":"#8B5A2B","force":"Medium","wrapper":"Sumatra d''Équateur","vitolas":[],"story":"2013 — le manoir où Led Zeppelin enregistra ; chez My Father."},{"name":"Jericho Hill","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"2014 — un vers de Johnny Cash, cape San Andrés ; chez My Father."},{"name":"Las Calaveras","color":"#1F1F1F","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Édition annuelle depuis 2014, une bague pour les morts de l''année."},{"name":"La Imperiosa","color":"#7A2E1E","force":"Medium-Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"2015 — la ligne régulière tirée de Las Calaveras ; chez My Father."},{"name":"Mil Días","color":"#6B4226","force":"Medium","wrapper":"Habano d''Équateur","vitolas":[],"story":"2020 — mille jours de mise au point, à La Alianza, chez E.P. Carrillo."}]' WHERE `name` = 'Crowned Heads';
UPDATE `brands` SET `gamme_en` = '[{"name":"Four Kicks","color":"#8B4513","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":["Corona Gorda","Robusto"],"story":"The founding range, rolled in Estelí at My Father. Full-bodied, peppery, tightly built — the Nicaraguan style as seen by a house that has no factory and therefore chooses its roller."},{"name":"Le Carême","color":"#4A3728","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":["Toro"],"story":"Born of a collaboration with Ernesto Perez-Carrillo and rolled at his factory, in the Dominican Republic. Dark broadleaf wrapper, cocoa and coffee — nothing to do with Four Kicks, and that is the point."},{"name":"Headley Grange","color":"#8B5A2B","force":"Medium","wrapper":"Ecuadorian Sumatra","vitolas":[],"story":"2013 — the manor where Led Zeppelin recorded; at My Father."},{"name":"Jericho Hill","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"2014 — a Johnny Cash lyric, San Andrés wrapper; at My Father."},{"name":"Las Calaveras","color":"#1F1F1F","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"Annual edition since 2014, a band for the year''s dead."},{"name":"La Imperiosa","color":"#7A2E1E","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"2015 — the regular line drawn from Las Calaveras; at My Father."},{"name":"Mil Días","color":"#6B4226","force":"Medium","wrapper":"Ecuadorian Habano","vitolas":[],"story":"2020 — a thousand days of development, at La Alianza, at E.P. Carrillo."}]' WHERE `name` = 'Crowned Heads';
UPDATE `brands` SET `gamme_es` = '[{"name":"Four Kicks","color":"#8B4513","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":["Corona Gorda","Robusto"],"story":"La gama fundacional, liada en Estelí en casa de My Father. Fuerte, apimentada, muy construida — el estilo nicaragüense visto por una casa que no tiene fábrica y elige por tanto a su torcedor."},{"name":"Le Carême","color":"#4A3728","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":["Toro"],"story":"Nacida de una colaboración con Ernesto Perez-Carrillo y liada en su casa, en la República Dominicana. Capa broadleaf oscura, cacao y café — nada que ver con Four Kicks, y ese es el propósito."},{"name":"Headley Grange","color":"#8B5A2B","force":"Medium","wrapper":"Sumatra de Ecuador","vitolas":[],"story":"2013 — la mansión donde grabó Led Zeppelin; en My Father."},{"name":"Jericho Hill","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (México)","vitolas":[],"story":"2014 — un verso de Johnny Cash, capa San Andrés; en My Father."},{"name":"Las Calaveras","color":"#1F1F1F","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"Edición anual desde 2014, una anilla para los muertos del año."},{"name":"La Imperiosa","color":"#7A2E1E","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"2015 — la línea regular sacada de Las Calaveras; en My Father."},{"name":"Mil Días","color":"#6B4226","force":"Medium","wrapper":"Habano de Ecuador","vitolas":[],"story":"2020 — mil días de puesta a punto, en La Alianza, en E.P. Carrillo."}]' WHERE `name` = 'Crowned Heads';
UPDATE `brands` SET `gamme_de` = '[{"name":"Four Kicks","color":"#8B4513","force":"Medium-Full","wrapper":"Habano aus Ecuador","vitolas":["Corona Gorda","Robusto"],"story":"Die Gründungslinie, in Estelí bei My Father gerollt. Kräftig, pfeffrig, streng gebaut — der nicaraguanische Stil, gesehen von einem Haus, das keine Manufaktur hat und daher seinen Roller wählt."},{"name":"Le Carême","color":"#4A3728","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":["Toro"],"story":"Aus einer Zusammenarbeit mit Ernesto Perez-Carrillo entstanden und bei ihm gerollt, in der Dominikanischen Republik. Dunkles Broadleaf-Deckblatt, Kakao und Kaffee — mit Four Kicks nichts gemein, und genau darum geht es."},{"name":"Headley Grange","color":"#8B5A2B","force":"Medium","wrapper":"Ecuadorianisches Sumatra","vitolas":[],"story":"2013 — das Herrenhaus, in dem Led Zeppelin aufnahm; bei My Father."},{"name":"Jericho Hill","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"2014 — eine Zeile von Johnny Cash, San-Andrés-Deckblatt; bei My Father."},{"name":"Las Calaveras","color":"#1F1F1F","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Jährliche Edition seit 2014, eine Bauchbinde für die Toten des Jahres."},{"name":"La Imperiosa","color":"#7A2E1E","force":"Medium-Full","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"2015 — die aus Las Calaveras abgeleitete reguläre Linie; bei My Father."},{"name":"Mil Días","color":"#6B4226","force":"Medium","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"2020 — tausend Tage Entwicklung, bei La Alianza, E.P. Carrillo."}]' WHERE `name` = 'Crowned Heads';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Four Kicks","color":"#8B4513","force":"Medium-Full","wrapper":"厄瓜多尔哈瓦那种","vitolas":["Corona Gorda","Robusto"],"story":"奠基产品线，在埃斯特利的 My Father 卷制。浓郁、带胡椒、结构严谨——这是一家没有工厂、因而能自主挑选卷制者的企业眼中的尼加拉瓜风格。"},{"name":"Le Carême","color":"#4A3728","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":["Toro"],"story":"与埃内斯托·佩雷斯-卡里略合作而生，并在他位于多米尼加共和国的工厂卷制。深色宽叶茄衣，可可与咖啡——与 Four Kicks 毫无关系，而这正是用意所在。"},{"name":"Headley Grange","color":"#8B5A2B","force":"Medium","wrapper":"厄瓜多尔苏门答腊","vitolas":[],"story":"2013年——齐柏林飞艇录音的那座庄园；在 My Father 制作。"},{"name":"Jericho Hill","color":"#4A3728","force":"Medium-Full","wrapper":"圣安德烈斯（墨西哥）","vitolas":[],"story":"2014年——约翰尼·卡什的一句歌词，圣安德烈斯茄衣；在 My Father 制作。"},{"name":"Las Calaveras","color":"#1F1F1F","force":"Full","wrapper":"未公开","vitolas":[],"story":"自2014年起的年度版，以茄标纪念当年逝者。"},{"name":"La Imperiosa","color":"#7A2E1E","force":"Medium-Full","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"2015年——从 Las Calaveras 派生的常规线；在 My Father 制作。"},{"name":"Mil Días","color":"#6B4226","force":"Medium","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"2020年——一千天的打磨，在 E.P. Carrillo 的 La Alianza 制作。"}]' WHERE `name` = 'Crowned Heads';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Four Kicks","color":"#8B4513","force":"Medium-Full","wrapper":"هابانو إكوادوري","vitolas":["Corona Gorda","Robusto"],"story":"السلسلة التأسيسية، ملفوفة في إستيلي عند «ماي فاذر». قوية، فلفلية، محكمة البناء — الأسلوب النيكاراغوي كما تراه دار بلا مصنع، ولذلك تختار ملفّها."},{"name":"Le Carême","color":"#4A3728","force":"Full","wrapper":"Connecticut Broadleaf","vitolas":["Toro"],"story":"وُلدت من تعاون مع إرنستو بيريز-كاريّو وتُلفّ عنده، في الجمهورية الدومينيكية. غلاف برودليف داكن، كاكاو وقهوة — لا صلة لها بـ«فور كيكس»، وهذا هو المقصد."},{"name":"Headley Grange","color":"#8B5A2B","force":"Medium","wrapper":"سومطرة إكوادوري","vitolas":[],"story":"2013 — القصر الذي سجّلت فيه Led Zeppelin؛ لدى My Father."},{"name":"Jericho Hill","color":"#4A3728","force":"Medium-Full","wrapper":"سان أندريس (المكسيك)","vitolas":[],"story":"2014 — بيتٌ من أغنية لجوني كاش، غلاف سان أندريس؛ لدى My Father."},{"name":"Las Calaveras","color":"#1F1F1F","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"إصدار سنوي منذ 2014، حزامٌ لموتى السنة."},{"name":"La Imperiosa","color":"#7A2E1E","force":"Medium-Full","wrapper":"هابانو إكوادوري","vitolas":[],"story":"2015 — الخطّ المنتظم المستخلَص من Las Calaveras؛ لدى My Father."},{"name":"Mil Días","color":"#6B4226","force":"Medium","wrapper":"هابانو إكوادوري","vitolas":[],"story":"2020 — ألف يوم من التطوير، في La Alianza لدى E.P. Carrillo."}]' WHERE `name` = 'Crowned Heads';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : crownedheads.com (Headley Grange, 2013 ; Jericho Hill, 2014 ; Las Calaveras, édition annuelle depuis 2014 ; La Imperiosa, 2015 ; Mil Días, 2020) — les quatre premières chez My Father, Mil Días à La Alianza') WHERE `name` = 'Crowned Heads' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── Illusione ──
UPDATE `brands` SET `gamme` = '[{"name":"Epernay","color":"#C2B280","force":"Medium","wrapper":"Corojo de Jalapa","vitolas":["Corona","Robusto"],"story":"Le versant crémeux de la maison, nommé d''après la ville du champagne. Pain grillé, beurre, foin — un cigare de milieu de journée que sa finesse rend plus long en bouche que son gabarit ne le laisse croire."},{"name":"Illusione Original Documents","color":"#8B7355","force":"Full","wrapper":"Corojo 99","vitolas":["Lancero"],"story":"Le format fin défendu par la marque, quand tout le marché montait en diamètre. Sec, poivré, sans concession : la démonstration que la finesse concentre au lieu de diluer."},{"name":"Cruzado","color":"#8B5A2B","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"2007 — la seconde marque de Dion Giolito, sur les tabacs d''Aganorsa."},{"name":"Rothchildes","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"2013 — un seul format court, cape San Andrés, prix contenu."},{"name":"Fume d''Amour","color":"#C9A96E","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"2015 — des vitoles aux noms de lieux nicaraguayens."},{"name":"OneOff","color":"#3E4A6B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Une marque italienne des années 2000, rachetée par Illusione en 2018 et roulée chez Aganorsa."},{"name":"Garagiste","color":"#6B4226","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"2019 — le mot des petits vignerons, pour un cigare corsé."}]' WHERE `name` = 'Illusione';
UPDATE `brands` SET `gamme_en` = '[{"name":"Epernay","color":"#C2B280","force":"Medium","wrapper":"Jalapa Corojo","vitolas":["Corona","Robusto"],"story":"The creamy side of the house, named after the champagne town. Toasted bread, butter, hay — a midday cigar whose slenderness makes it longer on the palate than its size suggests."},{"name":"Illusione Original Documents","color":"#8B7355","force":"Full","wrapper":"Corojo 99","vitolas":["Lancero"],"story":"The slender format the brand defended while the whole market grew fatter. Dry, peppery, uncompromising: the proof that thinness concentrates instead of diluting."},{"name":"Cruzado","color":"#8B5A2B","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"2007 — Dion Giolito''s second brand, on Aganorsa tobaccos."},{"name":"Rothchildes","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"2013 — a single short size, San Andrés wrapper, moderate price."},{"name":"Fume d''Amour","color":"#C9A96E","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"2015 — vitolas named after Nicaraguan places."},{"name":"OneOff","color":"#3E4A6B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"An Italian brand of the 2000s, bought by Illusione in 2018 and rolled at Aganorsa."},{"name":"Garagiste","color":"#6B4226","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"2019 — the word of small winemakers, for a full-bodied cigar."}]' WHERE `name` = 'Illusione';
UPDATE `brands` SET `gamme_es` = '[{"name":"Epernay","color":"#C2B280","force":"Medium","wrapper":"Corojo de Jalapa","vitolas":["Corona","Robusto"],"story":"La vertiente cremosa de la casa, con el nombre de la ciudad del champán. Pan tostado, mantequilla, heno — un cigarro de media jornada cuya finura lo hace más largo en boca de lo que su calibre haría pensar."},{"name":"Illusione Original Documents","color":"#8B7355","force":"Full","wrapper":"Corojo 99","vitolas":["Lancero"],"story":"El formato fino defendido por la marca cuando todo el mercado subía de cepo. Seco, apimentado, sin concesiones: la demostración de que la finura concentra en lugar de diluir."},{"name":"Cruzado","color":"#8B5A2B","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"2007 — la segunda marca de Dion Giolito, con tabacos de Aganorsa."},{"name":"Rothchildes","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (México)","vitolas":[],"story":"2013 — un solo formato corto, capa San Andrés, precio contenido."},{"name":"Fume d''Amour","color":"#C9A96E","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"2015 — vitolas con nombres de lugares nicaragüenses."},{"name":"OneOff","color":"#3E4A6B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Una marca italiana de los años 2000, comprada por Illusione en 2018 y liada en Aganorsa."},{"name":"Garagiste","color":"#6B4226","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"2019 — la palabra de los pequeños viticultores, para un puro fuerte."}]' WHERE `name` = 'Illusione';
UPDATE `brands` SET `gamme_de` = '[{"name":"Epernay","color":"#C2B280","force":"Medium","wrapper":"Corojo aus Jalapa","vitolas":["Corona","Robusto"],"story":"Die cremige Seite des Hauses, benannt nach der Champagnerstadt. Röstbrot, Butter, Heu — eine Zigarre für die Tagesmitte, deren Schlankheit sie länger am Gaumen macht, als ihr Format vermuten lässt."},{"name":"Illusione Original Documents","color":"#8B7355","force":"Full","wrapper":"Corojo 99","vitolas":["Lancero"],"story":"Das schlanke Format, das die Marke verteidigte, während der ganze Markt dicker wurde. Trocken, pfeffrig, kompromisslos: der Beweis, dass Schlankheit konzentriert statt verdünnt."},{"name":"Cruzado","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"2007 — die zweite Marke von Dion Giolito, auf Aganorsa-Tabaken."},{"name":"Rothchildes","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"2013 — ein einziges kurzes Format, San-Andrés-Deckblatt, moderater Preis."},{"name":"Fume d''Amour","color":"#C9A96E","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"2015 — Vitolas mit Namen nicaraguanischer Orte."},{"name":"OneOff","color":"#3E4A6B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Eine italienische Marke der 2000er, 2018 von Illusione gekauft und bei Aganorsa gerollt."},{"name":"Garagiste","color":"#6B4226","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"2019 — das Wort der kleinen Winzer, für eine kräftige Zigarre."}]' WHERE `name` = 'Illusione';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Epernay","color":"#C2B280","force":"Medium","wrapper":"哈拉帕可乐多","vitolas":["Corona","Robusto"],"story":"这家奶润的一面，以香槟之城命名。烤面包、黄油、干草——一支午间的雪茄，其纤细令余味比尺寸所暗示的更长。"},{"name":"Illusione Original Documents","color":"#8B7355","force":"Full","wrapper":"Corojo 99","vitolas":["Lancero"],"story":"在整个市场一路加粗时，这个品牌所捍卫的细身尺寸。干、带胡椒、毫不妥协：细身浓缩而非稀释的明证。"},{"name":"Cruzado","color":"#8B5A2B","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"2007年——迪翁·乔利托的第二个品牌，用 Aganorsa 烟叶。"},{"name":"Rothchildes","color":"#4A3728","force":"Medium-Full","wrapper":"圣安德烈斯（墨西哥）","vitolas":[],"story":"2013年——单一短尺寸，圣安德烈斯茄衣，价格克制。"},{"name":"Fume d''Amour","color":"#C9A96E","force":"Medium","wrapper":"未公开","vitolas":[],"story":"2015年——以尼加拉瓜地名命名的各尺寸。"},{"name":"OneOff","color":"#3E4A6B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"2000年代的一个意大利品牌，2018年被 Illusione 买下，在 Aganorsa 卷制。"},{"name":"Garagiste","color":"#6B4226","force":"Full","wrapper":"未公开","vitolas":[],"story":"2019年——小酒农的那个词，用在一支浓烈的雪茄上。"}]' WHERE `name` = 'Illusione';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Epernay","color":"#C2B280","force":"Medium","wrapper":"كوروخو خالابا","vitolas":["Corona","Robusto"],"story":"الوجه القشدي للدار، مسمّى على اسم مدينة الشمبانيا. خبز محمّص وزبدة وقشّ — سيجار منتصف النهار، تجعله نحافته أطول في الفم مما يوحي به حجمه."},{"name":"Illusione Original Documents","color":"#8B7355","force":"Full","wrapper":"Corojo 99","vitolas":["Lancero"],"story":"المقاس النحيل الذي دافعت عنه العلامة بينما كانت السوق كلّها تزداد سماكة. جافّ، فلفلي، بلا مساومة: برهان على أن النحافة تركّز ولا تخفّف."},{"name":"Cruzado","color":"#8B5A2B","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"2007 — العلامة الثانية لديون جوليتو، على أتبغة Aganorsa."},{"name":"Rothchildes","color":"#4A3728","force":"Medium-Full","wrapper":"سان أندريس (المكسيك)","vitolas":[],"story":"2013 — قياس قصير واحد، غلاف سان أندريس، ثمن معتدل."},{"name":"Fume d''Amour","color":"#C9A96E","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"2015 — فيتولات بأسماء أماكن نيكاراغوية."},{"name":"OneOff","color":"#3E4A6B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"علامة إيطالية من الألفينيات، اشترتها Illusione سنة 2018 وتُلفّ لدى Aganorsa."},{"name":"Garagiste","color":"#6B4226","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"2019 — كلمة صغار الكرّامين، لسيجار قويّ."}]' WHERE `name` = 'Illusione';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : illusionecigars.com (Cruzado, 2007 ; Rothchildes, 2013 ; Fume d''Amour, 2015 ; Haut 10, 2016, les dix ans ; OneOff, marque rachetée en 2018 ; Garagiste, 2019)') WHERE `name` = 'Illusione' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── Southern Draw ──
UPDATE `brands` SET `gamme` = '[{"name":"Rose of Sharon","color":"#C9A96E","force":"Light-Medium","wrapper":"Connecticut d''Équateur","vitolas":["Robusto","Toro","Corona"],"story":"La gamme qui porte le prénom de Sharon Holt. Cape Connecticut d''Équateur, registre doux — c''est l''entrée du catalogue, et celle par laquelle la maison s''est fait connaître."},{"name":"Kudzu","color":"#4A2C1A","force":"Full","wrapper":"Assemblage roulé chez A.J. Fernández","vitolas":["Robusto","Toro"],"story":"Le kudzu est une liane envahissante du Sud des États-Unis, qui recouvre tout ce qu''elle touche. C''est le versant corsé du catalogue, et le nom n''est pas neutre."},{"name":"Jacobs Ladder","color":"#3A2A20","force":"Full","wrapper":"Assemblage roulé chez A.J. Fernández","vitolas":["Brimstone","Robusto"],"story":"La gamme la plus dense, aux vitoles nommées en vocabulaire biblique — Brimstone, le soufre. La maison assume l''imagerie."},{"name":"Quickdraw","color":"#8B5A2B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"2015 — les petits formats de la maison, en plusieurs capes."},{"name":"Firethorn","color":"#B22222","force":"Medium-Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"2016 — le pyracantha, arbuste du Sud américain, en cape Habano d''Équateur."},{"name":"Desert Rose","color":"#8B1A6B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"2018 — dédiée aux femmes de la famille Holt, dit la maison."},{"name":"Fraternal Order","color":"#3E4A6B","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"2019, pour Cigars International d''abord, national depuis 2020 — les ordres fraternels, par couleur de bague."}]' WHERE `name` = 'Southern Draw';
UPDATE `brands` SET `gamme_en` = '[{"name":"Rose of Sharon","color":"#C9A96E","force":"Light-Medium","wrapper":"Ecuadorian Connecticut","vitolas":["Robusto","Toro","Corona"],"story":"The range that carries Sharon Holt''s name. Ecuadorian Connecticut wrapper, a mild register — it is the entry to the catalogue, and the one that made the house known."},{"name":"Kudzu","color":"#4A2C1A","force":"Full","wrapper":"Rolled at A.J. Fernández","vitolas":["Robusto","Toro"],"story":"Kudzu is an invasive vine of the American South that covers everything it touches. This is the fuller side of the catalogue, and the name is not neutral."},{"name":"Jacobs Ladder","color":"#3A2A20","force":"Full","wrapper":"Rolled at A.J. Fernández","vitolas":["Brimstone","Robusto"],"story":"The densest range, its vitolas named in biblical vocabulary — Brimstone, sulphur. The house owns the imagery."},{"name":"Quickdraw","color":"#8B5A2B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"2015 — the house''s small sizes, in several wrappers."},{"name":"Firethorn","color":"#B22222","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"2016 — the firethorn shrub of the American South, in Ecuadorian Habano."},{"name":"Desert Rose","color":"#8B1A6B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"2018 — dedicated to the women of the Holt family, the house says."},{"name":"Fraternal Order","color":"#3E4A6B","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"2019, for Cigars International first, national since 2020 — fraternal orders, by band colour."}]' WHERE `name` = 'Southern Draw';
UPDATE `brands` SET `gamme_es` = '[{"name":"Rose of Sharon","color":"#C9A96E","force":"Light-Medium","wrapper":"Connecticut de Ecuador","vitolas":["Robusto","Toro","Corona"],"story":"La gama que lleva el nombre de Sharon Holt. Capa Connecticut de Ecuador, registro suave: es la entrada del catálogo, y aquella por la que la casa se dio a conocer."},{"name":"Kudzu","color":"#4A2C1A","force":"Full","wrapper":"Liada en A.J. Fernández","vitolas":["Robusto","Toro"],"story":"El kudzu es una liana invasora del Sur de Estados Unidos que cubre todo lo que toca. Es la vertiente fuerte del catálogo, y el nombre no es neutro."},{"name":"Jacobs Ladder","color":"#3A2A20","force":"Full","wrapper":"Liada en A.J. Fernández","vitolas":["Brimstone","Robusto"],"story":"La gama más densa, con vitolas nombradas en vocabulario bíblico: Brimstone, el azufre. La casa asume la imaginería."},{"name":"Quickdraw","color":"#8B5A2B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"2015 — los formatos pequeños de la casa, en varias capas."},{"name":"Firethorn","color":"#B22222","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"2016 — el espino de fuego del Sur estadounidense, en capa Habano de Ecuador."},{"name":"Desert Rose","color":"#8B1A6B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"2018 — dedicada a las mujeres de la familia Holt, dice la casa."},{"name":"Fraternal Order","color":"#3E4A6B","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"2019, para Cigars International primero, nacional desde 2020 — las órdenes fraternales, por color de anilla."}]' WHERE `name` = 'Southern Draw';
UPDATE `brands` SET `gamme_de` = '[{"name":"Rose of Sharon","color":"#C9A96E","force":"Light-Medium","wrapper":"Ecuador-Connecticut","vitolas":["Robusto","Toro","Corona"],"story":"Die Linie, die Sharon Holts Namen trägt. Ecuador-Connecticut-Deckblatt, mildes Register — sie ist der Einstieg in den Katalog und hat das Haus bekannt gemacht."},{"name":"Kudzu","color":"#4A2C1A","force":"Full","wrapper":"Bei A.J. Fernández gerollt","vitolas":["Robusto","Toro"],"story":"Kudzu ist eine wuchernde Kletterpflanze des amerikanischen Südens, die alles überzieht, was sie berührt. Das ist die kräftige Seite des Katalogs, und der Name ist nicht neutral."},{"name":"Jacobs Ladder","color":"#3A2A20","force":"Full","wrapper":"Bei A.J. Fernández gerollt","vitolas":["Brimstone","Robusto"],"story":"Die dichteste Linie, ihre Vitolas nach biblischem Vokabular benannt — Brimstone, der Schwefel. Das Haus steht zu der Bildsprache."},{"name":"Quickdraw","color":"#8B5A2B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"2015 — die kleinen Formate des Hauses, in mehreren Deckblättern."},{"name":"Firethorn","color":"#B22222","force":"Medium-Full","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"2016 — der Feuerdorn des amerikanischen Südens, in ecuadorianischem Habano."},{"name":"Desert Rose","color":"#8B1A6B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"2018 — den Frauen der Familie Holt gewidmet, sagt das Haus."},{"name":"Fraternal Order","color":"#3E4A6B","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"2019, zuerst für Cigars International, national seit 2020 — Bruderschaften, nach Farbe der Bauchbinde."}]' WHERE `name` = 'Southern Draw';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Rose of Sharon","color":"#C9A96E","force":"Light-Medium","wrapper":"厄瓜多尔康涅狄格","vitolas":["Robusto","Toro","Corona"],"story":"以 Sharon Holt 之名命名的一条线。厄瓜多尔康涅狄格茄衣，风格柔和——它是目录的入门款，也是让这家为人所知的一款。"},{"name":"Kudzu","color":"#4A2C1A","force":"Full","wrapper":"于 A.J. Fernández 卷制","vitolas":["Robusto","Toro"],"story":"葛藤是美国南方的一种入侵藤蔓，所触之处尽被覆盖。这是目录中浓烈的一侧，名字并不中性。"},{"name":"Jacobs Ladder","color":"#3A2A20","force":"Full","wrapper":"于 A.J. Fernández 卷制","vitolas":["Brimstone","Robusto"],"story":"最厚重的一条线，尺寸以圣经词汇命名——Brimstone，硫磺。公司坦然接受这套意象。"},{"name":"Quickdraw","color":"#8B5A2B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"2015年——公司的小尺寸系列，多种茄衣。"},{"name":"Firethorn","color":"#B22222","force":"Medium-Full","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"2016年——美国南方的火棘，厄瓜多尔 Habano 茄衣。"},{"name":"Desert Rose","color":"#8B1A6B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"2018年——公司说，献给霍尔特家族的女性。"},{"name":"Fraternal Order","color":"#3E4A6B","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"2019年先供 Cigars International，2020年起全国发售——兄弟会，按茄标颜色区分。"}]' WHERE `name` = 'Southern Draw';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Rose of Sharon","color":"#C9A96E","force":"Light-Medium","wrapper":"كونيتيكت إكوادوري","vitolas":["Robusto","Toro","Corona"],"story":"السلسلة التي تحمل اسم شارون هولت. غلاف كونيتيكت إكوادوري ومزاج لطيف — وهي مدخل الكتالوج، وبها عُرفت الدار."},{"name":"Kudzu","color":"#4A2C1A","force":"Full","wrapper":"ملفوف عند أ. ج. فرنانديز","vitolas":["Robusto","Toro"],"story":"الكودزو نبتة متسلّقة غازية في جنوب الولايات المتحدة تغطّي كلّ ما تلمسه. وهو الوجه القويّ في الكتالوج، والاسم ليس محايدًا."},{"name":"Jacobs Ladder","color":"#3A2A20","force":"Full","wrapper":"ملفوف عند أ. ج. فرنانديز","vitolas":["Brimstone","Robusto"],"story":"أكثف السلاسل، ومقاساتها مسمّاة بمفردات توراتية — «برِمستون»، أي الكبريت. والدار تتبنّى هذه الصور."},{"name":"Quickdraw","color":"#8B5A2B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"2015 — القياسات الصغيرة للدار، بعدّة أغلفة."},{"name":"Firethorn","color":"#B22222","force":"Medium-Full","wrapper":"هابانو إكوادوري","vitolas":[],"story":"2016 — شجيرة الفايرثورن في الجنوب الأمريكي، بغلاف هابانو إكوادوري."},{"name":"Desert Rose","color":"#8B1A6B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"2018 — مهدًى لنساء عائلة هولت، كما تقول الدار."},{"name":"Fraternal Order","color":"#3E4A6B","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"2019، لـCigars International أوّلًا، ثم وطنيًّا منذ 2020 — الأخويات، بحسب لون الحزام."}]' WHERE `name` = 'Southern Draw';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : southerndrawcigars.com et cigardojo.com « Southern Draw Announces Fraternal Order Duo » (Quickdraw, 2015 ; Firethorn, 2016 ; Desert Rose, 2018 ; Fraternal Order, 2019, d''abord pour Cigars International, national depuis 2020) — chez A.J. Fernández') WHERE `name` = 'Southern Draw' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── Drew Estate ──
UPDATE `brands` SET `gamme` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"La gamme infusée qui a fait connaître la maison — arômes de thé, herbes botaniques, essence florale. Format Robusto (54 x 127mm). Cape d''Indonésie sur un assemblage que Drew Estate ne détaille pas. C''est le cigare qui a fait entrer dans le genre des fumeurs que la puissance des assemblages traditionnels aurait écartés. Contesté chez les puristes, adoré de ses amateurs.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonésie"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"L''autre visage de Drew Estate — le plus sérieux, le plus recherché. Cape Connecticut Broadleaf Habano sur triple ligero nicaraguayen. Notes de café ristretto, cacao amer, mûre. La Flying Pig, perfecto court et trapu, est le format le plus rare et le plus cher de la gamme.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Créée par les torcedores eux-mêmes — les ouvriers de l''usine voulaient un cigare aussi bon que la Liga Privada à un prix qu''ils pouvaient payer. Assemblage proche du No.9, sous une cape d''Équateur moins coûteuse. Notes de chocolat, café, poivre.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Équateur"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"Habano d''Équateur","vitolas":[],"story":"Le cigare de Willy Herrera, l''assembleur d''El Titan de Bronze à Miami engagé en 2011, lancé au début de 2013 sur une recette composée lors de sa première visite à Estelí. Le recensement de cet atlas le prenait pour une maison."},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"Kentucky séché au feu","vitolas":[],"story":"Du tabac de Kentucky séché à la fumée de bois, comme celui des pipes, dans un cigare roulé à Estelí. Une ligne, pas une maison."},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf du Connecticut","vitolas":[],"story":"2013 — le cigare que les rouleurs se font, dit la maison : broadleaf, rustique, un seul format au départ."},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"2015 — la version corsée d''Herrera Estelí, cape San Andrés."}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `gamme_en` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"The infused best-seller — aromas of tea, botanical herbs, floral essence. Robusto format (54 x 127mm). The cigar that introduced millions of Americans to cigars without intimidating them with traditional blend power. Indonesian wrapper over Drew Estate proprietary blend. Controversial among purists, adored by fans.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesian"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"The other face of Drew Estate — the most serious, the most sought after. Connecticut Broadleaf Habano wrapper over Nicaraguan triple ligero. Ristretto coffee, bitter cocoa, blackberry. The Flying Pig, a short stubby perfecto, is the rarest and dearest shape in the range.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Created by the torcedores themselves — factory workers who wanted a cigar as good as Liga Privada at an accessible price. Blend close to the No.9, less expensive Ecuadorian wrapper. Notes of chocolate, coffee, pepper. The most successful worker rebellion in the industry.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuadorian"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"Ecuadorian Habano","vitolas":[],"story":"Willy Herrera''s cigar — the El Titan de Bronze blender from Miami, hired in 2011 — launched in early 2013 on a recipe composed during his first visit to Estelí. This atlas''s census took it for a house."},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"Fire-cured Kentucky","vitolas":[],"story":"Kentucky tobacco cured over wood smoke, as for pipes, in a cigar rolled in Estelí. A line, not a house."},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","wrapper":"Connecticut broadleaf","vitolas":[],"story":"2013 — the cigar rollers make for themselves, the house says: broadleaf, rustic, a single size at first."},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"2015 — the full-bodied version of Herrera Estelí, San Andrés wrapper."}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `gamme_es` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"El superventas infusionado: aromas de té, hierbas botánicas, esencia floral. Robusto (54 x 127mm). El puro que introdujo a millones de estadounidenses en el cigarro sin asustarlos con la potencia de las ligas tradicionales. Capa indonesia sobre liga propia de Drew Estate. Controvertido entre los puristas, adorado por sus fieles.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesia"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"La otra cara de Drew Estate: la más seria, la más buscada. Capa Connecticut Broadleaf Habano sobre triple ligero nicaragüense. Café ristretto, cacao amargo, mora. La Flying Pig, un perfecto corto y rechoncho, es el formato más raro y más caro de la gama.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Creada por los propios torcedores: los obreros de la fábrica querían un puro tan bueno como Liga Privada a precio accesible. Liga cercana a la del No.9, capa ecuatoriana más económica. Chocolate, café, pimienta. La revuelta obrera más lograda del sector.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuador"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"Habano de Ecuador","vitolas":[],"story":"El puro de Willy Herrera, el ligador de El Titan de Bronze en Miami contratado en 2011, lanzado a principios de 2013 con una receta compuesta en su primera visita a Estelí. El censo de este atlas lo tomaba por una casa."},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"Kentucky curado al fuego","vitolas":[],"story":"Tabaco de Kentucky curado al humo de leña, como el de las pipas, en un puro liado en Estelí. Una línea, no una casa."},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf de Connecticut","vitolas":[],"story":"2013 — el puro que los torcedores se hacen, dice la casa: broadleaf, rústico, un solo formato al principio."},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","wrapper":"San Andrés (México)","vitolas":[],"story":"2015 — la versión fuerte de Herrera Estelí, capa San Andrés."}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `gamme_de` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"Der infundierte Bestseller — Tee, botanische Kräuter, blumige Essenz. Robusto (54 x 127 mm). Die Zigarre, die Millionen Amerikaner an die Zigarre heranführte, ohne sie mit der Kraft traditioneller Mischungen zu erschrecken. Indonesisches Deckblatt über hauseigener Drew-Estate-Mischung. Umstritten bei Puristen, geliebt von ihren Anhängern.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesien"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"Das andere Gesicht von Drew Estate — das ernsteste, das begehrteste. Deckblatt Connecticut Broadleaf Habano über nicaraguanischem Triple Ligero. Ristretto, bittere Kakao, Brombeere. Die Flying Pig, ein kurzes, gedrungenes Perfecto, ist das seltenste und teuerste Format der Serie.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Von den Torcedores selbst geschaffen — die Arbeiter der Fabrik wollten eine Zigarre so gut wie die Liga Privada zu zugänglichem Preis. Mischung nah am No.9, günstigeres ecuadorianisches Deckblatt. Schokolade, Kaffee, Pfeffer. Die gelungenste Arbeiterrevolte der Branche.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuador"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"Die Zigarre von Willy Herrera, dem 2011 engagierten Blender von El Titan de Bronze in Miami, Anfang 2013 lanciert nach einem Rezept aus seinem ersten Besuch in Estelí. Die Zählung dieses Atlas hielt sie für ein Haus."},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"Feuergetrockneter Kentucky","vitolas":[],"story":"Kentucky-Tabak, über Holzrauch getrocknet wie für Pfeifen, in einer in Estelí gerollten Zigarre. Eine Linie, kein Haus."},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","wrapper":"Connecticut-Broadleaf","vitolas":[],"story":"2013 — die Zigarre, die sich die Roller selbst machen, sagt das Haus: Broadleaf, rustikal, anfangs ein einziges Format."},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"2015 — die kräftige Version von Herrera Estelí, San-Andrés-Deckblatt."}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `gamme_zh` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"浸香系列的畅销之作——茶、植物香草、花香精油。罗布图规格（54 x 127 毫米）。正是这支雪茄让数百万美国人接触雪茄，而不必先被传统配方的力度吓退。印尼茄衣，内裹 Drew Estate 自有配方。纯粹派对它争议不断，拥趸却爱之如命。","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"印尼"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"Drew Estate 的另一副面孔——最正经，也最抢手。康涅狄格宽叶哈瓦那茄衣，内裹尼加拉瓜三重利赫罗。里斯特雷托咖啡、苦可可、黑莓。短而粗壮的 Flying Pig 是全系中最稀有也最昂贵的规格。","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"由卷制师们自己创制——厂里的工人想要一支像 Liga Privada 一样好、价格却够得着的雪茄。配方接近 No.9，改用更便宜的厄瓜多尔茄衣。巧克力、咖啡、胡椒。这是行业里最成功的一场工人起义。","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"厄瓜多尔"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"威利·埃雷拉的雪茄——他是迈阿密 El Titan de Bronze 的调配师，2011年受聘——2013年初推出，配方在他首次造访埃斯特利时调成。本图集的普查曾把它当作一家公司。"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"烟熏干燥的肯塔基烟叶","vitolas":[],"story":"像烟斗烟草那样用木柴烟熏干燥的肯塔基烟叶，卷进一支埃斯特利制作的雪茄。是一条线，不是一家公司。"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","wrapper":"康涅狄格 broadleaf","vitolas":[],"story":"2013年——公司说这是卷工给自己做的雪茄：broadleaf，粗犷，起初只有一种尺寸。"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","wrapper":"圣安德烈斯（墨西哥）","vitolas":[],"story":"2015年——Herrera Estelí 的浓烈版，圣安德烈斯茄衣。"}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `gamme_ar` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"الأكثر مبيعًا بين المنقوعات — شاي، أعشاب نباتية، خلاصة زهرية. روبوستو (54 × 127 مم). السيجار الذي عرّف ملايين الأمريكيين على التدخين دون أن يُفزعهم بقوّة الخلطات التقليدية. غلاف إندونيسي فوق خلطة خاصة بـDrew Estate. مثير للجدل عند المتشدّدين، محبوب عند أنصاره.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"إندونيسي"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"الوجه الآخر لـDrew Estate — الأكثر جدّية والأكثر طلبًا. غلاف كونيتيكت برودليف هابانو فوق ليغيرو نيكاراغوي ثلاثي. قهوة ريستريتو، كاكاو مرّ، توت أسود. أما الـFlying Pig، وهو بيرفيكتو قصير ممتلئ، فأندر قياسات المجموعة وأغلاها.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"أنشأها اللافّون أنفسهم — أراد عمّال المصنع سيجارًا بجودة الليغا بريفادا وبسعر في المتناول. خلطة قريبة من الـNo.9، بغلاف إكوادوري أقلّ كلفة. شوكولاتة، قهوة، فلفل. أنجح ثورة عمالية في هذه الصناعة.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"إكوادوري"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","wrapper":"هابانو إكوادوري","vitolas":[],"story":"سيجار ويلي إيريرا، مزّاج El Titan de Bronze في ميامي الذي استُقدم سنة 2011، أُطلق في مطلع 2013 على وصفة رُكّبت في زيارته الأولى لإستيلي. وكان إحصاء هذا الأطلس يحسبه دارًا."},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","wrapper":"كنتاكي مجفَّف بالنار","vitolas":[],"story":"تبغ كنتاكي مجفَّف على دخان الخشب كتبغ الغليون، في سيجار يُلفّ في إستيلي. خطٌّ لا دار."},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","wrapper":"برودليف كونيتيكت","vitolas":[],"story":"2013 — السيجار الذي يصنعه اللفّافون لأنفسهم، كما تقول الدار: برودليف، خشن، قياس واحد في البداية."},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","wrapper":"سان أندريس (المكسيك)","vitolas":[],"story":"2015 — النسخة القويّة من Herrera Estelí، غلاف سان أندريس."}]' WHERE `name` = 'Drew Estate';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : drewestate.com (Nica Rustica, 2013, broadleaf, le cigare du rouleur ; Herrera Estelí Norteño, 2015, San Andrés)') WHERE `name` = 'Drew Estate' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── My Father ──
UPDATE `brands` SET `gamme` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"Torpedo (52 x 152mm). Assemblage nicaraguayen complexe, cape Habano oscuro d''Équateur. Notes de cèdre rouge, café macchiato, poivre cubèbe. La référence de la maison — chaque lot est attendu comme un millésime.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro d''Équateur"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"Lancé en 2008, le cigare inaugural de la maison. Cape Connecticut naturel d''Équateur sur nicaraguayen. Notes de crème, noisette, épices légères. Malgré son statut de premier essai, le No.1 n''a jamais quitté le catalogue — Pepín avait vu juste dès le début.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut d''Équateur"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"Hommage aux manufactures cubaines d''avant-révolution. Cape maduro Connecticut Broadleaf sur nicaraguayen vieilli. Notes de chocolat noir, café froid, mélasse. Plus douce que la Le Bijou 1922, plus accessible, tout aussi remarquable. L''entrée dans l''univers My Father pour les amateurs de maduro.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","wrapper":"Broadleaf du Connecticut","vitolas":[],"story":"2010 — la ligne au nom du fils, cape broadleaf."},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","wrapper":"Puro nicaraguayen","vitolas":[],"story":"2012 — un puro nicaraguayen pressé, cape cultivée au soleil sur les fermes de la famille."},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","wrapper":"Broadleaf du Connecticut","vitolas":[],"story":"2012 — la marque de Janny García, la fille de la maison."},{"name":"El Centurión","color":"#7A2E1E","force":"Full","wrapper":"Habano du Nicaragua","vitolas":[],"story":"Une édition limitée de 2007, revenue en ligne régulière en 2013."}]' WHERE `name` = 'My Father';
UPDATE `brands` SET `gamme_en` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"Torpedo (52 x 152mm). Complex Nicaraguan blend, Ecuadorian Habano oscuro wrapper. Red cedar, macchiato, cubeb pepper. The house benchmark — each batch is awaited like a vintage.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Ecuadorian Habano Oscuro"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"Launched in 2008, the house''s inaugural cigar. Ecuadorian Connecticut natural wrapper over Nicaraguan. Cream, hazelnut, light spice. For all its status as a first attempt, the No.1 has never left the catalogue — Pepín had it right from the start.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Ecuadorian Connecticut"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"A tribute to the pre-revolution Cuban factories. Connecticut Broadleaf maduro wrapper over aged Nicaraguan. Dark chocolate, cold coffee, molasses. Milder than the Le Bijou 1922, more approachable, every bit as remarkable. The way into the My Father world for maduro lovers.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","wrapper":"Connecticut broadleaf","vitolas":[],"story":"2010 — the line in the son''s name, broadleaf wrapper."},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","wrapper":"Nicaraguan puro","vitolas":[],"story":"2012 — a box-pressed Nicaraguan puro, sun-grown wrapper from the family''s farms."},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","wrapper":"Connecticut broadleaf","vitolas":[],"story":"2012 — the brand of Janny García, the house''s daughter."},{"name":"El Centurión","color":"#7A2E1E","force":"Full","wrapper":"Nicaraguan Habano","vitolas":[],"story":"A 2007 limited edition, back as a regular line in 2013."}]' WHERE `name` = 'My Father';
UPDATE `brands` SET `gamme_es` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"Torpedo (52 x 152mm). Liga nicaragüense compleja, capa Habano oscuro de Ecuador. Cedro rojo, macchiato, pimienta cubeba. La referencia de la casa: cada lote se espera como una añada.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro de Ecuador"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"Lanzado en 2008, el puro inaugural de la casa. Capa Connecticut natural de Ecuador sobre nicaragüense. Crema, avellana, especias ligeras. Pese a su condición de primer intento, el No.1 nunca ha salido del catálogo: Pepín acertó desde el principio.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut de Ecuador"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"Homenaje a las manufacturas cubanas de antes de la revolución. Capa maduro Connecticut Broadleaf sobre nicaragüense envejecido. Chocolate negro, café frío, melaza. Más suave que la Le Bijou 1922, más accesible, igual de notable. La puerta de entrada al universo My Father para los aficionados al maduro.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","wrapper":"Broadleaf de Connecticut","vitolas":[],"story":"2010 — la línea con el nombre del hijo, capa broadleaf."},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","wrapper":"Puro nicaragüense","vitolas":[],"story":"2012 — un puro nicaragüense prensado, capa cultivada al sol en las fincas de la familia."},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","wrapper":"Broadleaf de Connecticut","vitolas":[],"story":"2012 — la marca de Janny García, la hija de la casa."},{"name":"El Centurión","color":"#7A2E1E","force":"Full","wrapper":"Habano de Nicaragua","vitolas":[],"story":"Una edición limitada de 2007, vuelta como línea regular en 2013."}]' WHERE `name` = 'My Father';
UPDATE `brands` SET `gamme_de` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"Torpedo (52 x 152 mm). Komplexe nicaraguanische Mischung, Deckblatt Habano Oscuro aus Ecuador. Rote Zeder, Macchiato, Kubebenpfeffer. Der Maßstab des Hauses — jede Charge wird wie ein Jahrgang erwartet.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro aus Ecuador"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"2008 lanciert, die erste Zigarre des Hauses. Deckblatt Connecticut Natural aus Ecuador über Nicaraguanischem. Sahne, Haselnuss, leichte Gewürze. Trotz ihres Status als Erstling hat die No.1 den Katalog nie verlassen — Pepín lag von Anfang an richtig.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut aus Ecuador"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"Eine Hommage an die kubanischen Manufakturen vor der Revolution. Deckblatt Connecticut Broadleaf Maduro über gereiftem Nicaragua-Tabak. Zartbitterschokolade, kalter Kaffee, Melasse. Milder als die Le Bijou 1922, zugänglicher, ebenso bemerkenswert. Der Einstieg in die Welt von My Father für Maduro-Liebhaber.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","wrapper":"Connecticut-Broadleaf","vitolas":[],"story":"2010 — die Linie im Namen des Sohnes, Broadleaf-Deckblatt."},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","wrapper":"Nicaraguanischer Puro","vitolas":[],"story":"2012 — ein gepresster nicaraguanischer Puro, sonnengereiftes Deckblatt von den Farmen der Familie."},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","wrapper":"Connecticut-Broadleaf","vitolas":[],"story":"2012 — die Marke von Janny García, der Tochter des Hauses."},{"name":"El Centurión","color":"#7A2E1E","force":"Full","wrapper":"Nicaraguanisches Habano","vitolas":[],"story":"Eine limitierte Auflage von 2007, seit 2013 als reguläre Linie zurück."}]' WHERE `name` = 'My Father';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"鱼雷型（52 x 152 毫米）。尼加拉瓜复杂配方，厄瓜多尔深色哈瓦那茄衣。红雪松、玛奇朵、荜澄茄。这是这家老号的标杆——每一批都像年份酒一样被等待。","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"厄瓜多尔 Habano Oscuro"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"2008 年推出，是这家老号的开山之作。厄瓜多尔康涅狄格自然色茄衣，内裹尼加拉瓜烟叶。奶油、榛子、轻盈香料。尽管只是初次尝试，No.1 却从未退出目录——佩平一开始就想对了。","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"厄瓜多尔 Connecticut"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"向革命前的古巴烟厂致敬。康涅狄格宽叶马杜罗茄衣，包裹陈化的尼加拉瓜烟叶。黑巧克力、冷咖啡、糖蜜。比 Le Bijou 1922 更柔和，更平易，却同样出色。这是马杜罗爱好者进入 My Father 世界的入口。","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","wrapper":"康涅狄格 broadleaf","vitolas":[],"story":"2010年——以儿子命名的系列，broadleaf 茄衣。"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","wrapper":"尼加拉瓜纯料","vitolas":[],"story":"2012年——方压的尼加拉瓜纯料，家族农场日晒茄衣。"},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","wrapper":"康涅狄格 broadleaf","vitolas":[],"story":"2012年——家族女儿詹妮·加西亚的品牌。"},{"name":"El Centurión","color":"#7A2E1E","force":"Full","wrapper":"尼加拉瓜 Habano","vitolas":[],"story":"2007年的限量版，2013年作为常规线回归。"}]' WHERE `name` = 'My Father';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"توربيدو (52 × 152 مم). خلطة نيكاراغوية معقّدة، وغلاف هابانو داكن من الإكوادور. أرز أحمر، ماكياتو، فلفل كبابة. إنه مرجع الدار — تُنتظر كل دفعة انتظار سنةٍ من الكروم.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro من الإكوادور"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"أُطلق عام 2008، وهو سيجار الدار الأول. غلاف كونيتيكت طبيعي من الإكوادور فوق تبغ نيكاراغوي. قشدة، بندق، توابل خفيفة. ورغم كونه محاولة أولى، لم يغادر الـNo.1 القائمة قط — فقد أصاب بيبين منذ البداية.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut من الإكوادور"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"تحية إلى المصانع الكوبية لما قبل الثورة. غلاف كونيتيكت برودليف مادورو فوق تبغ نيكاراغوي معتَّق. شوكولاتة داكنة، قهوة باردة، دبس. أنعم من الـLe Bijou 1922، وأسهل تناولًا، ولا يقلّ تميّزًا. إنه مدخل عشّاق المادورو إلى عالم My Father.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","wrapper":"برودليف كونيتيكت","vitolas":[],"story":"2010 — الخطّ باسم الابن، غلاف برودليف."},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","wrapper":"نيكاراغوي خالص","vitolas":[],"story":"2012 — سيجار نيكاراغوي خالص مضغوط، غلاف مزروع تحت الشمس من مزارع العائلة."},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","wrapper":"برودليف كونيتيكت","vitolas":[],"story":"2012 — علامة جاني غارسيا، ابنة الدار."},{"name":"El Centurión","color":"#7A2E1E","force":"Full","wrapper":"هابانو نيكاراغوي","vitolas":[],"story":"إصدار محدود من 2007، عاد خطًّا منتظمًا سنة 2013."}]' WHERE `name` = 'My Father';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : myfathercigars.com (Jaime García Reserva Especial, 2010 ; Flor de las Antillas, 2012 ; La Dueña, 2012, la marque de Janny García ; El Centurión, ligne régulière depuis 2013)') WHERE `name` = 'My Father' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── Tatuaje ──
UPDATE `brands` SET `gamme` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"Habano de Ecuador","vitolas":["Robusto","Corona"],"story":"La série d''origine, celle qui porte la marque depuis 2003. Grammaire cubaine, matière nicaraguayenne : poivre, cuir, une combustion lente et régulière qui doit tout au roulage des García."},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"Le registre plus doux de la maison, pensé pour la journée plutôt que pour la soirée. Moins de poivre, plus de bois et de pain grillé."},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut d''Équateur","vitolas":[],"story":"Le versant doux de Pete Johnson — Connecticut d''Équateur sur tabacs nicaraguayens, du nom d''une ville de Cuba. Le recensement de cet atlas la prenait pour une maison."},{"name":"Black Label","color":"#1F1F1F","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"2007 — d''abord vendue en jarres, la ligne « à la cubaine » de Pete Johnson."},{"name":"La Riqueza","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf du Connecticut","vitolas":[],"story":"2008 — cape broadleaf sur tabacs nicaraguayens."},{"name":"Monster Series","color":"#4A3728","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"L''édition annuelle d''Halloween depuis 2008 — Frank, Drac, Face, Wolfman —, en boîtes-cercueils comptées."},{"name":"Ambos Mundos","color":"#8B5A2B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"2010 — les deux mondes, un cigare de prix contenu."}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `gamme_en` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"Ecuadorian Habano","vitolas":["Robusto","Corona"],"story":"The original line, which has carried the brand since 2003. Cuban grammar, Nicaraguan matter: pepper, leather, and a slow, even burn that owes everything to the Garcías'' rolling."},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"The gentler register of the house, meant for the daytime rather than the evening. Less pepper, more wood and toasted bread."},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"Ecuadorian Connecticut","vitolas":[],"story":"Pete Johnson''s mild side — Ecuadorian Connecticut over Nicaraguan tobaccos, named after a town in Cuba. This atlas''s census took it for a house."},{"name":"Black Label","color":"#1F1F1F","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"2007 — first sold in jars, Pete Johnson''s Cuban-style line."},{"name":"La Riqueza","color":"#3A2A1E","force":"Full","wrapper":"Connecticut broadleaf","vitolas":[],"story":"2008 — broadleaf wrapper over Nicaraguan tobaccos."},{"name":"Monster Series","color":"#4A3728","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"The annual Halloween edition since 2008 — Frank, Drac, Face, Wolfman —, in numbered coffin boxes."},{"name":"Ambos Mundos","color":"#8B5A2B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"2010 — both worlds, a moderately priced cigar."}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `gamme_es` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"Habano de Ecuador","vitolas":["Robusto","Corona"],"story":"La serie original, la que lleva la marca desde 2003. Gramática cubana, materia nicaragüense: pimienta, cuero, y una combustión lenta y regular que se lo debe todo al liado de los García."},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"El registro más suave de la casa, pensado para el día antes que para la noche. Menos pimienta, más madera y pan tostado."},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut de Ecuador","vitolas":[],"story":"El lado suave de Pete Johnson — Connecticut de Ecuador sobre tabacos nicaragüenses, con el nombre de un pueblo de Cuba. El censo de este atlas la tomaba por una casa."},{"name":"Black Label","color":"#1F1F1F","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"2007 — vendida primero en jarras, la línea «a la cubana» de Pete Johnson."},{"name":"La Riqueza","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf de Connecticut","vitolas":[],"story":"2008 — capa broadleaf sobre tabacos nicaragüenses."},{"name":"Monster Series","color":"#4A3728","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"La edición anual de Halloween desde 2008 — Frank, Drac, Face, Wolfman —, en cajas-ataúd contadas."},{"name":"Ambos Mundos","color":"#8B5A2B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"2010 — los dos mundos, un puro de precio contenido."}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `gamme_de` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"Habano aus Ecuador","vitolas":["Robusto","Corona"],"story":"Die ursprüngliche Serie, die die Marke seit 2003 trägt. Kubanische Grammatik, nicaraguanische Substanz: Pfeffer, Leder und ein langsamer, gleichmäßiger Abbrand, der allein der Rollkunst der Garcías zu verdanken ist."},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"Das sanftere Register des Hauses, eher für den Tag als für den Abend gedacht. Weniger Pfeffer, mehr Holz und Röstbrot."},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"Ecuadorianisches Connecticut","vitolas":[],"story":"Pete Johnsons milde Seite — ecuadorianisches Connecticut über nicaraguanischen Tabaken, nach einer Stadt in Kuba benannt. Die Zählung dieses Atlas hielt sie für ein Haus."},{"name":"Black Label","color":"#1F1F1F","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"2007 — zuerst in Gläsern verkauft, Pete Johnsons Linie nach kubanischer Art."},{"name":"La Riqueza","color":"#3A2A1E","force":"Full","wrapper":"Connecticut-Broadleaf","vitolas":[],"story":"2008 — Broadleaf-Deckblatt über nicaraguanischen Tabaken."},{"name":"Monster Series","color":"#4A3728","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die jährliche Halloween-Edition seit 2008 — Frank, Drac, Face, Wolfman —, in gezählten Sargkisten."},{"name":"Ambos Mundos","color":"#8B5A2B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"2010 — beide Welten, eine preiswerte Zigarre."}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"厄瓜多尔哈瓦那种","vitolas":["Robusto","Corona"],"story":"最初的系列，自2003年起就代表着这个品牌。古巴的语法，尼加拉瓜的原料：胡椒、皮革，以及缓慢均匀的燃烧——这全要归功于加西亚家族的卷制。"},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"这家更柔和的一面，为白天而非夜晚而设。胡椒更少，木质与烤面包更多。"},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"厄瓜多尔康涅狄格","vitolas":[],"story":"皮特·约翰逊的柔和一面——厄瓜多尔康涅狄格茄衣配尼加拉瓜烟叶，以古巴一座城镇命名。本图集的普查曾把它当作一家公司。"},{"name":"Black Label","color":"#1F1F1F","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"2007年——起初装在罐里卖，皮特·约翰逊的古巴风格系列。"},{"name":"La Riqueza","color":"#3A2A1E","force":"Full","wrapper":"康涅狄格 broadleaf","vitolas":[],"story":"2008年——broadleaf 茄衣配尼加拉瓜烟叶。"},{"name":"Monster Series","color":"#4A3728","force":"Full","wrapper":"未公开","vitolas":[],"story":"自2008年起的年度万圣节版——Frank、Drac、Face、Wolfman——限量棺材盒装。"},{"name":"Ambos Mundos","color":"#8B5A2B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"2010年——两个世界，一支价格克制的雪茄。"}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","wrapper":"هابانو إكوادوري","vitolas":["Robusto","Corona"],"story":"السلسلة الأصلية التي تحمل العلامة منذ 2003. قواعد كوبية ومادة نيكاراغوية: فلفل وجلد، واحتراق بطيء منتظم يدين بكل شيء للفّ آل غارسيا."},{"name":"Havana VI","color":"#B87333","force":"Medium","wrapper":"Corojo","vitolas":["Corona Gorda"],"story":"الوجه الألطف للدار، مصمَّم للنهار لا للمساء. فلفل أقل، وخشب وخبز محمّص أكثر."},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","wrapper":"كونيتيكت إكوادوري","vitolas":[],"story":"الجانب اللطيف عند بيت جونسون — كونيتيكت إكوادوري على أتبغة نيكاراغوية، باسم بلدة في كوبا. وكان إحصاء هذا الأطلس يحسبها دارًا."},{"name":"Black Label","color":"#1F1F1F","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"2007 — بِيعت أوّلًا في جرار، خطّ بيت جونسون على الطريقة الكوبية."},{"name":"La Riqueza","color":"#3A2A1E","force":"Full","wrapper":"برودليف كونيتيكت","vitolas":[],"story":"2008 — غلاف برودليف على أتبغة نيكاراغوية."},{"name":"Monster Series","color":"#4A3728","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"الإصدار السنوي للهالوين منذ 2008 — Frank وDrac وFace وWolfman — في علب على شكل توابيت معدودة."},{"name":"Ambos Mundos","color":"#8B5A2B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"2010 — العالمان، سيجار معتدل الثمن."}]' WHERE `name` = 'Tatuaje';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : tatuajecigars.com (Black Label, 2007, d''abord en jarres ; La Riqueza, 2008, broadleaf ; Monster Series, l''édition annuelle d''Halloween depuis 2008 ; Ambos Mundos, 2010)') WHERE `name` = 'Tatuaje' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── Fratello ──
UPDATE `brands` SET `gamme` = '[{"name":"Fratello Bianco","color":"#C9A96E","force":"Medium","wrapper":"Connecticut d''Équateur","vitolas":["Robusto","Toro"],"story":"Le versant clair du catalogue, sous cape Connecticut d''Équateur. C''est la gamme la plus accessible de la maison, et celle qui l''a fait entrer chez les détaillants."},{"name":"Fratello Oro","color":"#8B5A2B","force":"Medium-Full","wrapper":"Assemblage roulé à la Joya de Nicaragua","vitolas":["Robusto","Toro","Corona"],"story":"La gamme dorée, plus dense que la Bianco. Même atelier, même famille de tabacs, une composition plus affirmée."},{"name":"Navetta","color":"#4A2C1A","force":"Full","wrapper":"Assemblage roulé à la Joya de Nicaragua","vitolas":["Robusto","Toro"],"story":"« Navette », en italien. Le nom d''un ancien ingénieur de la NASA qui fait des cigares, et le versant le plus corsé de son catalogue."},{"name":"Fratello Classico","color":"#6B4226","force":"Medium-Full","wrapper":"Habano du Nicaragua","vitolas":[],"story":"L''assemblage des débuts, 2013, sous le seul nom Fratello, rebaptisé Classico en 2018."}]' WHERE `name` = 'Fratello';
UPDATE `brands` SET `gamme_en` = '[{"name":"Fratello Bianco","color":"#C9A96E","force":"Medium","wrapper":"Ecuadorian Connecticut","vitolas":["Robusto","Toro"],"story":"The pale side of the catalogue, under an Ecuadorian Connecticut wrapper. It is the house''s most accessible range, and the one that got it onto retailers'' shelves."},{"name":"Fratello Oro","color":"#8B5A2B","force":"Medium-Full","wrapper":"Rolled at Joya de Nicaragua","vitolas":["Robusto","Toro","Corona"],"story":"The golden range, denser than the Bianco. Same workshop, same family of tobaccos, a more assertive composition."},{"name":"Navetta","color":"#4A2C1A","force":"Full","wrapper":"Rolled at Joya de Nicaragua","vitolas":["Robusto","Toro"],"story":"\\"Shuttle\\", in Italian. The name of a former NASA engineer who makes cigars, and the fullest side of his catalogue."},{"name":"Fratello Classico","color":"#6B4226","force":"Medium-Full","wrapper":"Nicaraguan Habano","vitolas":[],"story":"The founding blend, 2013, under the Fratello name alone, renamed Classico in 2018."}]' WHERE `name` = 'Fratello';
UPDATE `brands` SET `gamme_es` = '[{"name":"Fratello Bianco","color":"#C9A96E","force":"Medium","wrapper":"Connecticut de Ecuador","vitolas":["Robusto","Toro"],"story":"La vertiente clara del catálogo, bajo capa Connecticut de Ecuador. Es la gama más accesible de la casa, y la que la metió en las tiendas."},{"name":"Fratello Oro","color":"#8B5A2B","force":"Medium-Full","wrapper":"Liada en Joya de Nicaragua","vitolas":["Robusto","Toro","Corona"],"story":"La gama dorada, más densa que la Bianco. Mismo taller, misma familia de tabacos, una composición más afirmada."},{"name":"Navetta","color":"#4A2C1A","force":"Full","wrapper":"Liada en Joya de Nicaragua","vitolas":["Robusto","Toro"],"story":"«Lanzadera», en italiano. El nombre de un antiguo ingeniero de la NASA que hace puros, y la vertiente más fuerte de su catálogo."},{"name":"Fratello Classico","color":"#6B4226","force":"Medium-Full","wrapper":"Habano de Nicaragua","vitolas":[],"story":"La ligada de los inicios, 2013, bajo el solo nombre Fratello, rebautizada Classico en 2018."}]' WHERE `name` = 'Fratello';
UPDATE `brands` SET `gamme_de` = '[{"name":"Fratello Bianco","color":"#C9A96E","force":"Medium","wrapper":"Ecuador-Connecticut","vitolas":["Robusto","Toro"],"story":"Die helle Seite des Katalogs, unter einem Ecuador-Connecticut-Deckblatt. Es ist die zugänglichste Linie des Hauses und diejenige, die es in den Handel gebracht hat."},{"name":"Fratello Oro","color":"#8B5A2B","force":"Medium-Full","wrapper":"Bei Joya de Nicaragua gerollt","vitolas":["Robusto","Toro","Corona"],"story":"Die goldene Linie, dichter als die Bianco. Dieselbe Werkstatt, dieselbe Tabakfamilie, eine bestimmtere Zusammensetzung."},{"name":"Navetta","color":"#4A2C1A","force":"Full","wrapper":"Bei Joya de Nicaragua gerollt","vitolas":["Robusto","Toro"],"story":"\\"Shuttle\\", auf Italienisch. Der Name eines ehemaligen NASA-Ingenieurs, der Zigarren macht, und die kräftigste Seite seines Katalogs."},{"name":"Fratello Classico","color":"#6B4226","force":"Medium-Full","wrapper":"Nicaraguanisches Habano","vitolas":[],"story":"Der Gründungs-Blend, 2013, nur unter dem Namen Fratello, 2018 in Classico umbenannt."}]' WHERE `name` = 'Fratello';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Fratello Bianco","color":"#C9A96E","force":"Medium","wrapper":"厄瓜多尔康涅狄格","vitolas":["Robusto","Toro"],"story":"目录中浅色的一侧，采用厄瓜多尔康涅狄格茄衣。这是这家最易入手的一条线，也是它得以进入零售渠道的那一条。"},{"name":"Fratello Oro","color":"#8B5A2B","force":"Medium-Full","wrapper":"于 Joya de Nicaragua 卷制","vitolas":["Robusto","Toro","Corona"],"story":"金色系列，比 Bianco 更为厚实。同一作坊，同一族烟叶，配方更为鲜明。"},{"name":"Navetta","color":"#4A2C1A","force":"Full","wrapper":"于 Joya de Nicaragua 卷制","vitolas":["Robusto","Toro"],"story":"意大利语中的「航天飞机」。这是一位做雪茄的前 NASA 工程师取的名字，也是他目录中最浓的一侧。"},{"name":"Fratello Classico","color":"#6B4226","force":"Medium-Full","wrapper":"尼加拉瓜 Habano","vitolas":[],"story":"创始配方，2013年，仅以 Fratello 之名，2018年更名 Classico。"}]' WHERE `name` = 'Fratello';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Fratello Bianco","color":"#C9A96E","force":"Medium","wrapper":"كونيتيكت إكوادوري","vitolas":["Robusto","Toro"],"story":"الوجه الفاتح في الكتالوج، تحت غلاف كونيتيكت إكوادوري. وهي أيسر سلاسل الدار منالًا، وبها دخلت المتاجر."},{"name":"Fratello Oro","color":"#8B5A2B","force":"Medium-Full","wrapper":"ملفوف في خويا دي نيكاراغوا","vitolas":["Robusto","Toro","Corona"],"story":"السلسلة الذهبية، أكثف من «بيانكو». الورشة نفسها وعائلة التبغ نفسها، بتركيبة أوضح."},{"name":"Navetta","color":"#4A2C1A","force":"Full","wrapper":"ملفوف في خويا دي نيكاراغوا","vitolas":["Robusto","Toro"],"story":"«المكوك» بالإيطالية. اسم اختاره مهندس ناسا سابق صار يصنع السيجار، وهو الوجه الأقوى في كتالوجه."},{"name":"Fratello Classico","color":"#6B4226","force":"Medium-Full","wrapper":"هابانو نيكاراغوي","vitolas":[],"story":"مزجة البدايات، 2013، باسم Fratello وحده، أُعيدت تسميتها Classico سنة 2018."}]' WHERE `name` = 'Fratello';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : fratellocigar.com (Classico : l''assemblage des débuts, 2013, rebaptisé Classico en 2018)') WHERE `name` = 'Fratello' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── 262 Cigars ──
UPDATE `brands` SET `gamme` = '[{"name":"Paradigm","color":"#5C4033","force":"Medium-Full","wrapper":"Assemblage nicaraguayen","vitolas":["Robusto","Toro","Corona"],"story":"Le premier cigare de la maison, sorti en 2010, cinq ans avant que la plupart des marques boutique d''aujourd''hui existent."},{"name":"Ideology","color":"#3A2E26","force":"Full","wrapper":"Assemblage nicaraguayen","vitolas":["Robusto","Toro"],"story":"Le versant corsé, venu après le Paradigm. Le nom continue la série des mots abstraits que la maison a choisis contre l''usage du métier."},{"name":"Revere","color":"#7A3B2E","force":"Medium-Full","wrapper":"Assemblage nicaraguayen","vitolas":["Lonsdale","Toro","Box-pressed Toro"],"story":"Nommé d''après Paul Revere. La maison est américaine de nom et d''imaginaire, nicaraguayenne de fabrication — l''écart est assumé."},{"name":"Allegiance","color":"#3E4A6B","force":"Medium-Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"2014 — l''allégeance, cape Habano d''Équateur."}]' WHERE `name` = '262 Cigars';
UPDATE `brands` SET `gamme_en` = '[{"name":"Paradigm","color":"#5C4033","force":"Medium-Full","wrapper":"Nicaraguan blend","vitolas":["Robusto","Toro","Corona"],"story":"The house''s first cigar, out in 2010, five years before most of today''s boutique brands existed."},{"name":"Ideology","color":"#3A2E26","force":"Full","wrapper":"Nicaraguan blend","vitolas":["Robusto","Toro"],"story":"The fuller side, following Paradigm. The name continues the series of abstract words the house chose against the trade''s custom."},{"name":"Revere","color":"#7A3B2E","force":"Medium-Full","wrapper":"Nicaraguan blend","vitolas":["Lonsdale","Toro","Box-pressed Toro"],"story":"Named after Paul Revere. The house is American in name and imagery, Nicaraguan in manufacture — and does not hide the gap."},{"name":"Allegiance","color":"#3E4A6B","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"2014 — allegiance, Ecuadorian Habano wrapper."}]' WHERE `name` = '262 Cigars';
UPDATE `brands` SET `gamme_es` = '[{"name":"Paradigm","color":"#5C4033","force":"Medium-Full","wrapper":"Ligada nicaragüense","vitolas":["Robusto","Toro","Corona"],"story":"El primer puro de la casa, salido en 2010, cinco años antes de que existieran la mayoría de las marcas boutique de hoy."},{"name":"Ideology","color":"#3A2E26","force":"Full","wrapper":"Ligada nicaragüense","vitolas":["Robusto","Toro"],"story":"La vertiente fuerte, llegada tras el Paradigm. El nombre continúa la serie de palabras abstractas que la casa eligió contra el uso del oficio."},{"name":"Revere","color":"#7A3B2E","force":"Medium-Full","wrapper":"Ligada nicaragüense","vitolas":["Lonsdale","Toro","Toro prensado"],"story":"Llamado así por Paul Revere. La casa es estadounidense de nombre e imaginario, nicaragüense de fabricación, y no oculta la distancia."},{"name":"Allegiance","color":"#3E4A6B","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"2014 — la lealtad, capa Habano de Ecuador."}]' WHERE `name` = '262 Cigars';
UPDATE `brands` SET `gamme_de` = '[{"name":"Paradigm","color":"#5C4033","force":"Medium-Full","wrapper":"Nicaraguanische Mischung","vitolas":["Robusto","Toro","Corona"],"story":"Die erste Zigarre des Hauses, 2010 erschienen, fünf Jahre bevor die meisten heutigen Boutiquemarken bestanden."},{"name":"Ideology","color":"#3A2E26","force":"Full","wrapper":"Nicaraguanische Mischung","vitolas":["Robusto","Toro"],"story":"Die kräftigere Seite, nach dem Paradigm. Der Name setzt die Reihe abstrakter Wörter fort, die das Haus gegen den Brauch der Branche gewählt hat."},{"name":"Revere","color":"#7A3B2E","force":"Medium-Full","wrapper":"Nicaraguanische Mischung","vitolas":["Lonsdale","Toro","Box-pressed Toro"],"story":"Nach Paul Revere benannt. Das Haus ist amerikanisch im Namen und in der Bildwelt, nicaraguanisch in der Fertigung — und verbirgt den Abstand nicht."},{"name":"Allegiance","color":"#3E4A6B","force":"Medium-Full","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"2014 — die Treue, ecuadorianisches Habano-Deckblatt."}]' WHERE `name` = '262 Cigars';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Paradigm","color":"#5C4033","force":"Medium-Full","wrapper":"尼加拉瓜配方","vitolas":["Robusto","Toro","Corona"],"story":"这家的第一支雪茄，2010 年问世，比今天多数精品品牌早了五年。"},{"name":"Ideology","color":"#3A2E26","force":"Full","wrapper":"尼加拉瓜配方","vitolas":["Robusto","Toro"],"story":"厚重的一面，继 Paradigm 之后。名字延续了这家逆行业惯例而取的一串抽象词。"},{"name":"Revere","color":"#7A3B2E","force":"Medium-Full","wrapper":"尼加拉瓜配方","vitolas":["Lonsdale","Toro","Box-pressed Toro"],"story":"取名自 Paul Revere。这家在名字与意象上是美国的，在制造上是尼加拉瓜的——它并不掩饰这段距离。"},{"name":"Allegiance","color":"#3E4A6B","force":"Medium-Full","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"2014年——效忠，厄瓜多尔 Habano 茄衣。"}]' WHERE `name` = '262 Cigars';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Paradigm","color":"#5C4033","force":"Medium-Full","wrapper":"مزيج نيكاراغويّ","vitolas":["Robusto","Toro","Corona"],"story":"أوّل سيجار للدار، صدر عام 2010، أي قبل خمس سنوات من ظهور معظم علامات البوتيك اليوم."},{"name":"Ideology","color":"#3A2E26","force":"Full","wrapper":"مزيج نيكاراغويّ","vitolas":["Robusto","Toro"],"story":"الوجه الأقوى، جاء بعد «باراديم». والاسم يواصل سلسلة الكلمات المجرّدة التي اختارتها الدار خلافًا لعُرف المهنة."},{"name":"Revere","color":"#7A3B2E","force":"Medium-Full","wrapper":"مزيج نيكاراغويّ","vitolas":["Lonsdale","Toro","Box-pressed Toro"],"story":"سُمّي على اسم بول ريفير. الدار أمريكية في الاسم والمخيال، نيكاراغوية في الصناعة — وهي لا تخفي المسافة."},{"name":"Allegiance","color":"#3E4A6B","force":"Medium-Full","wrapper":"هابانو إكوادوري","vitolas":[],"story":"2014 — الولاء، غلاف هابانو إكوادوري."}]' WHERE `name` = '262 Cigars';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : 262cigars.com et halfwheel.com « 262 Allegiance Toro » (Allegiance, 2014)') WHERE `name` = '262 Cigars' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── HVC Cigars ──
UPDATE `brands` SET `gamme` = '[{"name":"Serie A","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Perlas","Robusto","Toro"],"story":"Composée exclusivement de feuilles nicaraguayennes classées A, cultivées par Aganorsa. Le nom n''est pas une lettre décorative : c''est le classement de la feuille."},{"name":"Pan Caliente","color":"#A0522D","force":"Medium-Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Robusto","Toro"],"story":"« Pain chaud » — l''expression cubaine pour ce qui se vend aussitôt posé. C''est la gamme la plus vendue de la maison, et le nom était un pari sur elle-même."},{"name":"Hot Cake","color":"#6B4226","force":"Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Robusto","Toro"],"story":"La suite du Pan Caliente, dont elle traduit le nom en anglais. Même tabac Aganorsa, un registre plus corsé."},{"name":"La Rosa 520","color":"#7A2E1E","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"2015 — l''ancienne adresse du fondateur à La Havane ; dix ans fêtés à la PCA 2025."},{"name":"San Isidro","color":"#8B5A2B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Un quartier de La Havane, sur une bague."},{"name":"Cerro","color":"#4A3728","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le quartier où le fondateur est né et a grandi."}]' WHERE `name` = 'HVC Cigars';
UPDATE `brands` SET `gamme_en` = '[{"name":"Serie A","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Perlas","Robusto","Toro"],"story":"Blended exclusively from Nicaraguan class-A leaf grown by Aganorsa. The name is not a decorative letter: it is the leaf grade."},{"name":"Pan Caliente","color":"#A0522D","force":"Medium-Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Robusto","Toro"],"story":"\\"Hot bread\\" — the Cuban expression for what sells the moment it is set down. It is the house''s best-selling range, and the name was a bet on itself."},{"name":"Hot Cake","color":"#6B4226","force":"Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Robusto","Toro"],"story":"The follow-up to Pan Caliente, whose name it translates into English. Same Aganorsa tobacco, a fuller register."},{"name":"La Rosa 520","color":"#7A2E1E","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"2015 — the founder''s old address in Havana; ten years celebrated at PCA 2025."},{"name":"San Isidro","color":"#8B5A2B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"A Havana neighbourhood, on a band."},{"name":"Cerro","color":"#4A3728","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The neighbourhood where the founder was born and raised."}]' WHERE `name` = 'HVC Cigars';
UPDATE `brands` SET `gamme_es` = '[{"name":"Serie A","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Perlas","Robusto","Toro"],"story":"Compuesta exclusivamente de hojas nicaragüenses de clase A, cultivadas por Aganorsa. El nombre no es una letra decorativa: es la clasificación de la hoja."},{"name":"Pan Caliente","color":"#A0522D","force":"Medium-Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Robusto","Toro"],"story":"La expresión cubana para lo que se vende nada más ponerlo. Es la gama más vendida de la casa, y el nombre era una apuesta sobre sí misma."},{"name":"Hot Cake","color":"#6B4226","force":"Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Robusto","Toro"],"story":"La continuación del Pan Caliente, cuyo nombre traduce al inglés. Mismo tabaco Aganorsa, un registro más fuerte."},{"name":"La Rosa 520","color":"#7A2E1E","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"2015 — la antigua dirección del fundador en La Habana; diez años celebrados en la PCA 2025."},{"name":"San Isidro","color":"#8B5A2B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Un barrio de La Habana, en una anilla."},{"name":"Cerro","color":"#4A3728","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El barrio donde el fundador nació y creció."}]' WHERE `name` = 'HVC Cigars';
UPDATE `brands` SET `gamme_de` = '[{"name":"Serie A","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Perlas","Robusto","Toro"],"story":"Ausschließlich aus nicaraguanischem Blatt der Klasse A gemischt, von Aganorsa angebaut. Der Name ist kein dekorativer Buchstabe: Es ist die Blattklasse."},{"name":"Pan Caliente","color":"#A0522D","force":"Medium-Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Robusto","Toro"],"story":"\\"Warmes Brot\\" — der kubanische Ausdruck für das, was weggeht, kaum dass es daliegt. Es ist die meistverkaufte Linie des Hauses, und der Name war eine Wette auf sich selbst."},{"name":"Hot Cake","color":"#6B4226","force":"Full","wrapper":"Nicaragua (Aganorsa)","vitolas":["Robusto","Toro"],"story":"Die Fortsetzung der Pan Caliente, deren Namen sie ins Englische überträgt. Gleicher Aganorsa-Tabak, kräftigeres Register."},{"name":"La Rosa 520","color":"#7A2E1E","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"2015 — die alte Adresse des Gründers in Havanna; zehn Jahre gefeiert auf der PCA 2025."},{"name":"San Isidro","color":"#8B5A2B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Ein Viertel Havannas, auf einer Bauchbinde."},{"name":"Cerro","color":"#4A3728","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Das Viertel, in dem der Gründer geboren und aufgewachsen ist."}]' WHERE `name` = 'HVC Cigars';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Serie A","color":"#8B5A2B","force":"Medium-Full","wrapper":"尼加拉瓜（Aganorsa）","vitolas":["Perlas","Robusto","Toro"],"story":"全部以 Aganorsa 种植的尼加拉瓜 A 级烟叶调配。这个字母不是装饰，它就是烟叶的分级。"},{"name":"Pan Caliente","color":"#A0522D","force":"Medium-Full","wrapper":"尼加拉瓜（Aganorsa）","vitolas":["Robusto","Toro"],"story":"「热面包」——古巴俗语，形容一放上货架就卖光的东西。这是这家最畅销的一条线，而这个名字当初是对自己的一场下注。"},{"name":"Hot Cake","color":"#6B4226","force":"Full","wrapper":"尼加拉瓜（Aganorsa）","vitolas":["Robusto","Toro"],"story":"Pan Caliente 的后续，名字是它的英译。同样的 Aganorsa 烟叶，风格更浓。"},{"name":"La Rosa 520","color":"#7A2E1E","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"2015年——创始人在哈瓦那的旧地址；2025年 PCA 庆祝十周年。"},{"name":"San Isidro","color":"#8B5A2B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"哈瓦那的一个街区，印在茄标上。"},{"name":"Cerro","color":"#4A3728","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"创始人出生和成长的街区。"}]' WHERE `name` = 'HVC Cigars';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Serie A","color":"#8B5A2B","force":"Medium-Full","wrapper":"نيكاراغوا (أغانورسا)","vitolas":["Perlas","Robusto","Toro"],"story":"تُمزَج حصرًا من ورق نيكاراغوي من الفئة أ تزرعه أغانورسا. والحرف ليس زخرفًا: إنّه تصنيف الورقة."},{"name":"Pan Caliente","color":"#A0522D","force":"Medium-Full","wrapper":"نيكاراغوا (أغانورسا)","vitolas":["Robusto","Toro"],"story":"«الخبز الساخن» — التعبير الكوبي لما يُباع فور وضعه. وهي السلسلة الأكثر مبيعًا في الدار، وكان الاسم رهانًا على نفسه."},{"name":"Hot Cake","color":"#6B4226","force":"Full","wrapper":"نيكاراغوا (أغانورسا)","vitolas":["Robusto","Toro"],"story":"تكملة «بان كاليينتي»، وتترجم اسمها إلى الإنجليزية. تبغ أغانورسا نفسه، بمزاج أقوى."},{"name":"La Rosa 520","color":"#7A2E1E","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"2015 — العنوان القديم للمؤسّس في هافانا؛ احتُفل بعشر سنوات في PCA 2025."},{"name":"San Isidro","color":"#8B5A2B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"حيٌّ في هافانا، على حزام."},{"name":"Cerro","color":"#4A3728","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"الحيّ الذي وُلد فيه المؤسّس ونشأ."}]' WHERE `name` = 'HVC Cigars';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : hvccigars.com et cigar-coop.com « HVC La Rosa 520 10th Anniversary to Launch at PCA 2025 » (La Rosa 520, 2015, l''ancienne adresse de Reinier Lorenzo à La Havane ; San Isidro ; Cerro, le quartier de son enfance)') WHERE `name` = 'HVC Cigars' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';

-- ── Cornelius & Anthony ──
UPDATE `brands` SET `gamme` = '[{"name":"Cornelius","color":"#6B4226","force":"Medium-Full","wrapper":"Assemblage El Titan de Bronze","vitolas":["Robusto","Toro","Corona Gorda"],"story":"La première ligne, sortie en 2016, et la seule roulée à Miami. Elle porte le prénom de l''arrière-arrière-grand-père qui a commencé le tabac dans la famille."},{"name":"Daddy Mac","color":"#8B5A2B","force":"Medium","wrapper":"Assemblage nicaraguayen, chez La Zona","vitolas":["Robusto","Toro","Torpedo"],"story":"Le surnom d''un aïeul, sur un cigare fait à Estelí. C''est la ligne d''entrée de la maison, celle que l''on trouve le plus facilement."},{"name":"Aerial","color":"#4A5D3A","force":"Medium-Full","wrapper":"Assemblage nicaraguayen, chez La Zona","vitolas":["Robusto","Toro"],"story":"Sortie en 2017, roulée à La Zona. Le nom vient des câbles aériens que la famille tendait autrefois pour sécher la feuille."},{"name":"Meridian","color":"#3E4A6B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"IPCPR 2016 — avec Venganza, chez La Zona."},{"name":"Venganza","color":"#7A2E1E","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"IPCPR 2016 — la vengeance, le corsé de la maison."},{"name":"The Gent","color":"#C9A96E","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"IPCPR 2018 — le gentleman, avec Mistress, chez La Zona."}]' WHERE `name` = 'Cornelius & Anthony';
UPDATE `brands` SET `gamme_en` = '[{"name":"Cornelius","color":"#6B4226","force":"Medium-Full","wrapper":"El Titan de Bronze blend","vitolas":["Robusto","Toro","Corona Gorda"],"story":"The first line, out in 2016, and the only one rolled in Miami. It carries the first name of the great-great-grandfather who began the family in tobacco."},{"name":"Daddy Mac","color":"#8B5A2B","force":"Medium","wrapper":"Nicaraguan blend, at La Zona","vitolas":["Robusto","Toro","Torpedo"],"story":"A forebear''s nickname, on a cigar made in Estelí. It is the house''s entry line, the one most easily found."},{"name":"Aerial","color":"#4A5D3A","force":"Medium-Full","wrapper":"Nicaraguan blend, at La Zona","vitolas":["Robusto","Toro"],"story":"Out in 2017, rolled at La Zona. The name comes from the overhead wires the family once strung to cure the leaf."},{"name":"Meridian","color":"#3E4A6B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"IPCPR 2016 — with Venganza, at La Zona."},{"name":"Venganza","color":"#7A2E1E","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"IPCPR 2016 — vengeance, the house''s full-bodied one."},{"name":"The Gent","color":"#C9A96E","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"IPCPR 2018 — the gentleman, with Mistress, at La Zona."}]' WHERE `name` = 'Cornelius & Anthony';
UPDATE `brands` SET `gamme_es` = '[{"name":"Cornelius","color":"#6B4226","force":"Medium-Full","wrapper":"Ligada El Titan de Bronze","vitolas":["Robusto","Toro","Corona Gorda"],"story":"La primera línea, salida en 2016, y la única liada en Miami. Lleva el nombre del tatarabuelo que inició a la familia en el tabaco."},{"name":"Daddy Mac","color":"#8B5A2B","force":"Medium","wrapper":"Ligada nicaragüense, en La Zona","vitolas":["Robusto","Toro","Torpedo"],"story":"El apodo de un antepasado, sobre un puro hecho en Estelí. Es la línea de entrada de la casa, la más fácil de encontrar."},{"name":"Aerial","color":"#4A5D3A","force":"Medium-Full","wrapper":"Ligada nicaragüense, en La Zona","vitolas":["Robusto","Toro"],"story":"Salida en 2017, liada en La Zona. El nombre viene de los cables aéreos que la familia tendía antaño para secar la hoja."},{"name":"Meridian","color":"#3E4A6B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"IPCPR 2016 — con Venganza, en La Zona."},{"name":"Venganza","color":"#7A2E1E","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"IPCPR 2016 — la venganza, el fuerte de la casa."},{"name":"The Gent","color":"#C9A96E","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"IPCPR 2018 — el caballero, con Mistress, en La Zona."}]' WHERE `name` = 'Cornelius & Anthony';
UPDATE `brands` SET `gamme_de` = '[{"name":"Cornelius","color":"#6B4226","force":"Medium-Full","wrapper":"El-Titan-de-Bronze-Mischung","vitolas":["Robusto","Toro","Corona Gorda"],"story":"Die erste Linie, 2016 erschienen, und die einzige, die in Miami gerollt wird. Sie trägt den Vornamen des Ururgrossvaters, mit dem der Tabak in die Familie kam."},{"name":"Daddy Mac","color":"#8B5A2B","force":"Medium","wrapper":"Nicaraguanische Mischung, bei La Zona","vitolas":["Robusto","Toro","Torpedo"],"story":"Der Spitzname eines Vorfahren, auf einer in Estelí gemachten Zigarre. Es ist die Einstiegslinie des Hauses, die am leichtesten zu finden ist."},{"name":"Aerial","color":"#4A5D3A","force":"Medium-Full","wrapper":"Nicaraguanische Mischung, bei La Zona","vitolas":["Robusto","Toro"],"story":"2017 erschienen, bei La Zona gerollt. Der Name stammt von den Luftdrähten, die die Familie einst zum Trocknen des Blattes spannte."},{"name":"Meridian","color":"#3E4A6B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"IPCPR 2016 — mit Venganza, bei La Zona."},{"name":"Venganza","color":"#7A2E1E","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"IPCPR 2016 — die Rache, die kräftige des Hauses."},{"name":"The Gent","color":"#C9A96E","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"IPCPR 2018 — der Gentleman, mit Mistress, bei La Zona."}]' WHERE `name` = 'Cornelius & Anthony';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Cornelius","color":"#6B4226","force":"Medium-Full","wrapper":"El Titan de Bronze 配方","vitolas":["Robusto","Toro","Corona Gorda"],"story":"第一条线，2016 年问世，也是唯一在迈阿密卷制的一条。它取自那位把家族带进烟草行当的高祖父之名。"},{"name":"Daddy Mac","color":"#8B5A2B","force":"Medium","wrapper":"尼加拉瓜配方，产自 La Zona","vitolas":["Robusto","Toro","Torpedo"],"story":"一位先辈的绰号，用在埃斯特利做的雪茄上。这是这家的入门线，也最容易买到。"},{"name":"Aerial","color":"#4A5D3A","force":"Medium-Full","wrapper":"尼加拉瓜配方，产自 La Zona","vitolas":["Robusto","Toro"],"story":"2017 年问世，在 La Zona 卷制。名字来自家族当年为晾叶架设的空中铁丝。"},{"name":"Meridian","color":"#3E4A6B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"2016年 IPCPR——与 Venganza 同期，在 La Zona 制作。"},{"name":"Venganza","color":"#7A2E1E","force":"Full","wrapper":"未公开","vitolas":[],"story":"2016年 IPCPR——复仇，公司里浓烈的一款。"},{"name":"The Gent","color":"#C9A96E","force":"Medium","wrapper":"未公开","vitolas":[],"story":"2018年 IPCPR——绅士，与 Mistress 同期，在 La Zona 制作。"}]' WHERE `name` = 'Cornelius & Anthony';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Cornelius","color":"#6B4226","force":"Medium-Full","wrapper":"مزيج إل تيتان دي برونسي","vitolas":["Robusto","Toro","Corona Gorda"],"story":"الخطّ الأوّل، صدر عام 2016، وهو الوحيد الذي يُلَفّ في ميامي. يحمل اسم جدّ الجدّ الذي أدخل التبغ إلى العائلة."},{"name":"Daddy Mac","color":"#8B5A2B","force":"Medium","wrapper":"مزيج نيكاراغويّ، في لا زونا","vitolas":["Robusto","Toro","Torpedo"],"story":"لقب أحد الأجداد، على سيجار مصنوع في إستيلي. وهو خطّ الدار الأيسر منالًا، وأسهلها وجودًا."},{"name":"Aerial","color":"#4A5D3A","force":"Medium-Full","wrapper":"مزيج نيكاراغويّ، في لا زونا","vitolas":["Robusto","Toro"],"story":"صدر عام 2017، ويُلَفّ في لا زونا. والاسم من الأسلاك المعلّقة التي كانت العائلة تمدّها قديمًا لتجفيف الورق."},{"name":"Meridian","color":"#3E4A6B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"IPCPR 2016 — مع Venganza، لدى La Zona."},{"name":"Venganza","color":"#7A2E1E","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"IPCPR 2016 — الانتقام، القويّ في الدار."},{"name":"The Gent","color":"#C9A96E","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"IPCPR 2018 — الجنتلمان، مع Mistress، لدى La Zona."}]' WHERE `name` = 'Cornelius & Anthony';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; lot 5 bis : halfwheel.com « Cornelius & Anthony Adding Venganza, New Meridian » (IPCPR 2016) et cigar-coop.com « The Gent Robusto » (IPCPR 2018, avec Mistress, chez La Zona)') WHERE `name` = 'Cornelius & Anthony' AND COALESCE(`source`,'') NOT LIKE '%lot 5 bis :%';


INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, 'gamme', l.lang, SHA1(b.`gamme`), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Foundation Cigar Company','Dunbarton Tobacco & Trust','Alec Bradley','Crowned Heads','Illusione','Southern Draw','Drew Estate','My Father','Tatuaje','Fratello','262 Cigars','HVC Cigars','Cornelius & Anthony')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 218';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 218','systeme','lot_5_bis_quarante_lignes','marque',0,
   '41 lignes rangees dans le gamme de treize maisons, six langues : Foundation, Dunbarton, Alec Bradley, Crowned Heads, Illusione, Southern Draw, Drew Estate, My Father, Tatuaje, Fratello, 262, HVC, Cornelius & Anthony. Aucune maison creee'),
  (NULL,'migration 218','systeme','lignes_non_rangees','marque',0,
   'Tabak Especial, Deadwood, Isla del Sol : infuses, pas ajoutes sans regle ecrite. Indomina, Ultra, Haut 10, MJ12, Polpette, Stillwell Star, Red Meat Lovers, Fine & Rare, Gatekeeper, Court Reserve, Juarez : non sources dans ce lot');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Foundation Cigar Company','Dunbarton Tobacco & Trust','Alec Bradley','Crowned Heads','Illusione','Southern Draw','Drew Estate','My Father','Tatuaje','Fratello','262 Cigars','HVC Cigars','Cornelius & Anthony') AND `source` LIKE '%lot 5 bis :%') = 13 AS treize_sources,
  (SELECT `gamme_ar` LIKE '%Olmec%' AND `gamme_zh` LIKE '%Highclere%' FROM `brands` WHERE `name` = 'Foundation Cigar Company') AS foundation,
  (SELECT `gamme` LIKE '%Monster Series%' AND `gamme_de` LIKE '%La Riqueza%' FROM `brands` WHERE `name` = 'Tatuaje') AS tatuaje,
  (SELECT `gamme_es` LIKE '%Mil D%' FROM `brands` WHERE `name` = 'Crowned Heads') AS crowned,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 218') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
